window.__LEX={"G1700":"<h1>emou</h1>\n<p>Strong n° 1700 <i>Prononciation [em-oo']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>moi, mon, ma, mienne, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμοῦ</b>, <i>gén. de</i>  <i>ou de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμου - ἐμοῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n109 fois dans 104 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (18)</li>\n<li>Marc (8)</li>\n<li>Luc (18)</li>\n<li>Jean (25)</li>\n<li>Actes (6)</li>\n<li>Romains (7)</li>\n<li>2 Corinthiens (5)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>2 Timothée (4)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G1701":"<h1>empaigmos</h1>\n<p>Strong n° 1701 <i>Prononciation [emp-aheeg-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une moquerie, une raillerie, rire de, dérision</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμπαιγμός, οῦ (ὁ) :<br>      1</b> action de se jouer de, <i>d’où</i> raillerie, moquerie, SPT. <i>Ps. 37, 8 ; Sir. 27, 28 ; Ezech. 22, 4 ; 2 Macc. 7, 7 ;</i><br><b>      2</b> injure, mauvais traitement, <i>3 Macc. 5, 22 ;</i><br><b>      3</b> illusion, SPT. <i>Sap. 12, 25</i>.<br><span><b>Étym</b>. ἐμπαίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπαιγμος - ἐμπαιγμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1702":"<h1>empaizo</h1>\n<p>Strong n° 1702 <i>Prononciation [emp-aheed'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se jouer de, traiter en bagatelle\n<ol type=\"a\">\n<li>se moquer de, bafouer</li>\n<li>tromper, décevoir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·παίζω :<br>      1</b> jouer <i>ou</i> s’ébattre dans, <i>dat</i>. EUR. <i>Bacch. 867 ;</i> AR. <i>Th. 975 ;</i> LUC. <i>Lex. 5 ; par euphém. p</i>. συγγίγνομαι, SPT. <i>Judith 19, 25 ;</i><br><b>      2</b> se jouer de, se moquer de, <i>dat</i>. HDT. <i>4, 134 ;</i> SPT. <i>Ex. 10, 2 ; Num. 22, 29 ; Prov. 23, 35 ;</i> NT. <i>Matth. 20, 19 ; 27, 29, etc. ; au pass</i>. LUC. <i>Trag. 331 ;</i> ANTH. <i>10, 56</i>.<br><span><b>Étym</b>. ἐν, π.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπαιζω - ἐμπαίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Luc (5)</li>\n</ul>\n</td></tr>\n</table>","G1703":"<h1>empaiktes</h1>\n<p>Strong n° 1703 <i>Prononciation [emp-aheek-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un moqueur, un railleur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμπαίκτης, ου (ὁ)</b> qui se joue de, imposteur, SPT. <i>Esaï. 3, 4 ;</i> NT. <i>2Petr. 3, 3</i>.<br><span><b>Étym</b>. ἐμπαίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπαικτης - ἐμπαίκτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G1704":"<h1>emperipateo</h1>\n<p>Strong n° 1704 <i>Prononciation [em-per-ee-pat-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aller, parcourir, marcher, circuler parmi, aller et venir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·περιπατέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> se promener dans, <i>dat</i>. LUC. <i>Ind. 6 ;</i> ἔν τισι, SPT. <i>Lev. 26, 12 ;</i> NT. <i>2Cor. 6, 15,</i> au milieu de qqes personnes ; διαύλους τινάς, A. TAT. <i>1, 6,</i> aller et venir ici et là ;<br><b>      2</b> marcher sur, <i>acc</i>. SPT. <i>Job 1, 7 ; fig</i>. insulter, <i>dat</i>. PLUT. <i>M. 57</i> a.<br><span><b>Étym</b>. ἐν, π.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπεριπατεω - ἐμπεριπατέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1705":"<h1>empiplemi</h1>\n<p>Strong n° 1705 <i>Prononciation [em-pip'-lay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>remplir complètement</li>\n<li>se rassasier, assouvir un désir, satisfaire, à satiété</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·πίπλημι</b> <span>[πῑ]</span> <span>(<i>impf</i>. ἐνεπίμπλην, <i>f</i>. ἐμπλήσω, <i>ao</i>. ἐνέπλησα, <i>pf</i>. ἐμπέπληκα)</span><br><b>      1</b> remplir : δέπας, OD. <i>9, 209,</i> une coupe ; τί τινος (ἵππον ἀνδρῶν, OD. <i>8, 495 ;</i> θυλάκια ψάμμου, HDT. <i>3, 105, etc</i>.) remplir une chose d’une autre (le cheval de bois de guerriers ; des sacs de sable, <i>etc.) ; au pass</i>. être rempli, se remplir de : ἐνέπλησθεν δέ οἱ αἵματος ὀφθαλμοί, IL. <i>16, 348,</i> ses yeux se remplirent de sang ; ἔμπληντο βροτῶν ἀγοραί, OD. <i>8, 16,</i> les places étaient pleines de mortels ; <i>avec le dat</i>. αἵματι, PAUS. <i>3, 16, 10,</i> être couvert de sang, <i>en parl. d’un autel ; fig</i>. θυμὸν ὀδυνάων, OD. <i>19, 117,</i> remplir le cœur de douleurs ; τινὰ ἐλπίδων, ESCHN. <i>24, 27,</i> remplir qqn d’espérances ; <i>au pass</i>. ἐμπίμπλασθαι ὀργῆς, AR. <i>Vesp. 424 ;</i> πλεονεξίας, PLAT. <i>Criti. 121</i> b, <i>etc</i>. être plein de colère, d’ambition, <i>etc. ;</i><br><b>      2</b> rassasier : τινά, OD. <i>17, 503,</i> qqn ; <i>fig</i>. τινὰ τοῦ πολεμεῖν, ISOCR. <i>201,</i> rassasier qqn de guerre ; <i>au pass</i>. se rassasier, <i>avec un part</i>. οὐκ ἐνεπίμπλασο ὑπισχνούμενος, XÉN. <i>An. 7, 7, 46,</i> tu ne te rassasiais pas de promettre ; ἔμπλησο λέγων, AR. <i>Vesp. 603,</i> parle tant que tu voudras ;<br><b>      3</b> <i>fig</i>. accomplir : ἵμερον, A. RH. <i>4, 429,</i> satisfaire à un désir ; τὴν αὑτοῦ μοῖραν, PLAT. <i>Leg. 959</i> c, accomplir sa destinée ;<br><b><i>Moy.</i></b> :<br><b>      1</b> remplir pour soi : νηδύν, OD. <i>9, 296,</i> remplir son ventre ; ἄγγος τοῦ ὕδατος, HDT. <i>5, 12,</i> remplir son vase d’eau ; μένεος θυμόν, IL. <i>22, 312,</i> remplir son cœur de colère ;<br><b>      2</b> se rassasier de, <i>dat</i>. HDT. <i>1, 212 ; gén</i>. PLAT. <i>Pol. 272</i> c ; <i>abs</i>. OD. <i>7, 221</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. impér. épq</i>. ἐμπίπληθι, IL. <i>21, 311 ; dor. et att</i>. ἐμπίμπλη, AR. <i>Av. 1310. Fut. inf. épq</i>. ἐμπλησέμεν, IL. <i>11, 31. Ao.1 sbj. épq. 2 sg</i>. ἐνιπλήσῃς, OD. <i>19, 117 ; 3 pl</i>. ἐνιπλήσωσι, OD. <i>23, 358 — Pass. ao.1, 3 pl. éol. et dor</i>. ἐνέπλησθεν, IL. <i>16, 348 ; inf. épq</i>. ἐνιπλησθῆναι, OD. <i>11, 452. — Moy. ao.2, 3 sg. poét</i>. ἔμπλητο, IL. <i>21, 607 ; 3 pl. poét</i>. ἔμπληντο, OD. <i>8, 16. Fut. rare : inf</i>. ἐμπλήσεσθαι, ARAT. <i>1121 ; part</i>. ἐμπλησόμενος, APP. <i>Syr. 7. — Selon Cobet les formes attiques seraient</i> ἐμπίμπλημι, ἐμπίμπλαμαι (<i>de même que</i> ἐμπίμπρημι, ἐμπίμπραμαι) ; <i>les formes</i> ἐμπίπλημι, ἐμπίπλαμαι <i>seraient de grécité récente. La doctrine des gramm. anciens est que la dissimilation a lieu dans les formes où se trouvent les deux</i> μ, <i>le</i> μ <i>du radical tombant, d’où</i> ἐμπίπλημι, <i>mais</i> ἐνεπίμπλην (<i>de même que</i> ἐμπίπρημι, <i>mais</i> ἐνεπίμπρην) ; <i>l’Hérodien de Lentz (2, 842, 13) porte</i> ἐμπίπλη. — <i>Les inscript. att. n’offrent aucun exemple des deux verbes (v. Meisterh. à l’Index). Les mss. comme les meilleures éditions donnent pour les mêmes passages des formes différentes : dans</i> EUR. (<i>Ion 925) la vulg. est</i> ἐμπίμπλαμαι <i>adoptée par Dindorf ; Kirchhoff et Nauck écrivent</i> ἐμπίπλαμαι.<br><span><b>Étym</b>. ἐν, πίμπλημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπιπλημι - ἐμπί(μ)πλημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G1706":"<h1>empipto</h1>\n<p>Strong n° 1706 <i>Prononciation [em-pip'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tomber dans\n<ol type=\"a\">\n<li>tomber parmi des voleurs</li>\n<li>tomber dans un pouvoir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·πίπτω</b> <span>(<i>f</i>. ἐμπεσοῦμαι, <i>ao.2</i> ἐνέπεσον, <i>pf</i>. ἐμπέπτωκα)</span><br><b>      1</b> tomber dans <i>ou</i> sur : πόντῳ, OD. <i>4, 508,</i> dans la mer ; πέτρῃ, IL. <i>4, 108,</i> sur un rocher ; νηυσίν, IL. <i>16, 113,</i> sur les vaisseaux, <i>en parl. du feu ; rar. avec</i> ἐν : ἐν ὕλῃ, IL. <i>11, 155,</i> tomber sur une forêt, <i>en parl. du feu ;</i> εἰς τάφρους, XÉN. <i>Cyr. 3, 3, 64,</i> dans des fossés ; <i>p. anal</i>. εἰς δεσμωτήριον, DIN. <i>106, 14 ;</i> DÉM. <i>788, 17,</i> être jeté en prison ; <i>fig</i>. εἰς ἄτας, SOPH. <i>El. 216,</i> dans le malheur ; εἰς ὑποψίας, ANT. <i>116, 37,</i> être l’objet de soupçons ; εἰς νόσον, ANT. <i>113, 31,</i> tomber malade ; <i>qqf. avec</i> ἐπί <i>et l’acc</i>. ἐμπ. ἐπὶ συμφορήν, HDT. <i>7, 88,</i> tomber dans le malheur ;<br><b>      2</b> tomber sur, fondre sur : προμάχοις, OD. <i>24, 526,</i> sur les combattants des premiers rangs ; τοῖς πολεμίοις, XÉN. <i>Hipp. 8, 25,</i> sur l’ennemi ; ἐμπ. τινί, PD. <i>I. 1, 68,</i> s’attaquer à qqn, l’insulter ; <i>avec un suj. de chose :</i> ἐμπ. ἐς τὴν πόλιν, THC. <i>2, 48,</i> fondre sur la ville, <i>en parl. de la peste ;</i> ὕπνος ἐμπίπτει, PLAT. <i>Tim. 45</i> e, le sommeil m’envahit ; <i>particul. en parl. de sentiments ou de passions (crainte, amour, pitié, etc</i>.) ἐμπ. τινί, IL. <i>17, 625 ;</i> ESCHL. <i>Ag. 341 ;</i> SOPH. <i>Ph. 965, etc</i>. envahir l’âme de qqn ; χόλος ἔμπεσε θυμῷ, IL. <i>9, 436,</i> la colère envahit ton âme ;<br><b>      3</b> <i>p. suite,</i> s’offrir à : πάντα τὸν ἐμπίπτοντα ἐφόνευον, HDN <i>3, 9,</i> ils tuaient tout ce qui se présentait ; ἃ εἰς τὴν αἴσθησιν ἐμπίπτει, PLAT. <i>Rsp. 524</i> d, ce qui tombe sous les sens ; ἐμπ. εἰς τοὺς δικαστάς, PLUT. <i>Sol. 18,</i> être porté devant les juges, <i>en parl. d’un différend ; en parl. de bruits, de rumeurs :</i> μοι ἔπος ἔμπεσε θυμῷ, OD. <i>12, 266,</i> une parole est entrée dans mon cœur ; λόγος ἐμπέπτωκέ μοι, SOPH. <i>O.C. 1150,</i> un bruit est parvenu à mes oreilles ; <i>avec un suj. de pers</i>. en venir à parler de : τι, DÉM. <i>298, 11,</i> de qqe ch.<br><span><b>Étym</b>. ἐν, π.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπιπτω - ἐμπίπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>1 Timothée (3)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1707":"<h1>empleko</h1>\n<p>Strong n° 1707 <i>Prononciation [em-plek'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'engager</li>\n<li>de choses : s'empêtrer, impliquer, entraîner</li>\n<li>tresser, enlacer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·πλέκω</b> (<i>part. ao. pass</i>. ἐμπλακείς) :<br><b>      1</b> enlacer : χεῖρα, EUR. <i>Or. 262,</i> saisir qqn par la main ; αἰνίγματα, ESCHL. <i>Pr. 610,</i> parler par (tisser des) énigmes ; τινὰ εἰς φιλίαν τινός, POL. <i>27, 6, 11,</i> enlacer qqn dans l’amitié d’un autre ; <i>au pass</i>. être enlacé, ἡνίαισιν, EUR. <i>Hipp. 1236,</i> dans des rênes ; ἐν δεσμοῖσιν, AR. <i>Th. 1032,</i> dans des liens ; <i>fig</i>. ἐν πόνοις, PLAT. <i>Leg. 814</i> e ; ἐν κακοῖς, ISOCR. <i>181</i> e, être engagé dans des épreuves, dans des maux ; <i>abs</i>. former une liaison avec, se lier avec : τινι, POL. <i>25, 7, 1 ;</i> DS. <i>18, 2,</i> avec qqn ;<br><b>      2</b> tresser : ἐμπεπλεγμένος, ATH. <i>525</i> e, qui a les cheveux tressés.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. poét</i>. ἐνιπλέξω, CALL. <i>Del. 29</i>.<br><span><b>Étym</b>. ἐν, πλ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπλεκω - ἐμπλέκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Timothée (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1708":"<h1>emploke</h1>\n<p>Strong n° 1708 <i>Prononciation [em-plok-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un entrelacement, un tressage, un nœud</li>\n<li>un rassemblement élaboré de la chevelure en chignon</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμπλοκή, ῆς (ἡ) :<br>   I</b> <i>au propre :</i><br><b>      1</b> action de tresser, STR. <i>828 ;</i> NT. <i>1Petr. 3, 3 ;</i><br><b>      2</b> tresse, CLÉM. <i>233 ;</i><br><b>   II</b> <i>fig</i>. action d’en venir aux mains, POL. <i>18, 1, 11 ;</i> PLUT. <i>M. 916</i> d.<br><span><b>Étym</b>. ἐμπλέκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπλοκη - ἐμπλοκή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1709":"<h1>empneo</h1>\n<p>Strong n° 1709 <i>Prononciation [emp-neh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>respirer</li>\n<li>inhaler, aspirer, humer, exhaler</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·πνέω</b> <span>(<i>ao</i>. ἐνέπνευσα)</span><br><b>   I <i>intr</i>.<br>      1</b> souffler sur : πόντῳ, HÉS. <i>O. 506,</i> sur la mer, <i>en parl. du vent ;</i> μεταφρένῳ, IL. <i>17, 502,</i> sur le haut du dos, <i>en parl. de chevaux qui suivent qqn de si près qu’on sent leur souffle ;</i><br><b>      2</b> souffler dans : αὐλοῖς, ANTH. <i>9, 266,</i> dans une flûte ;<br><b>      3</b> amener le souffle en soi, respirer, vivre, ESCHL. <i>Ag. 671 ;</i> AR. <i>Th. 926 ; particul</i>. n’avoir plus que le souffle, respirer encore, SOPH. <i>Ph. 883 ;</i> EUR. <i>Alc. 205, Hipp. 1246 ;</i> ἕωσπερ ἂν ἐμπνέω, PLAT. <i>Ap. 29</i> d, tant que j’aurai le souffle ;<br><b>   II <i>tr</i>.<br>      1</b> pousser par son souffle : ἰστίον, HH. <i>Bacch. 33,</i> gonfler une voile ;<br><b>      2</b> <i>fig</i>. souffler dans le cœur <i>ou</i> dans l’esprit, inspirer : μένος τινί, IL. <i>20, 110 ;</i> θάρσος τινί, OD. <i>9, 381, etc</i>. souffler la colère <i>ou</i> la hardiesse dans l’âme de qqn ; <i>cf</i>. HÉS. <i>Th. 31 ;</i> PLAT. <i>Conv. 179</i> b, <i>etc. ; avec l’inf</i>. OD. <i>19, 138,</i> inspirer de, <i>etc. ; au pass</i>. être animé d’un souffle divin : εἰς μαντικήν, PLUT. <i>M. 421</i> b, pour faire des prédictions ; <i>abs</i>. être inspiré, LGN <i>15, 2 ;</i><br><b>   III</b> <i>avec le gén</i>. exhaler : ὀδμῆς, PÉRICT. (STOB. <i>488, 2</i>) un parfum ; <i>fig</i>. ἀπειλῆς καὶ φόνου, NT. <i>Ap. 9, 1,</i> respirer la menace et le meurtre.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. part. poét. non contr</i>. ἐμπνέων, EUR. <i>Hipp. 1246 ;</i> ἐμπνέοντα, SOPH. <i>Ph. 883 ; fém</i>. ἐμπνέουσα, EUR. <i>Alc. 205. Fut</i>. ἐμπνεύσομαι, EUR. <i>Andr. 554. — Épq. et ion</i>. ἐμπνείω, IL. <i>17, 502</i>.<br><span><b>Étym</b>. ἐν, πν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπνεω - ἐμπνέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1710":"<h1>emporeuomai</h1>\n<p>Strong n° 1710 <i>Prononciation [em-por-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aller pour affaires, voyager pour son travail, trafiquer, commercer</li>\n<li>d'une chose : importer pour la vente</li>\n<li>fournir, approvisionner</li>\n<li>utiliser une personne ou une chose pour un gain</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·πορεύομαι</b> <span>(<i>f</i>. -εύσομαι, <i>ao</i>. ἐνεπορεύθην)</span><br><b>   I</b> marcher dans <i>ou</i> vers, SOPH. <i>El. 405 ;</i> PLUT. <i>Pomp. 78 ;</i> ἐπὶ γαῖαν, SOPH. <i>O.R. 456,</i> aller vers un pays ; <i>abs</i>. EPICH. <i>fr. 26 Ahrens ; fig</i>. ἐμπ. εἰς ἰατρικήν, HPC. <i>3, 4,</i> suivre la carrière de la médecine, s’engager dans la médecine ; δίαιταν, EUR. <i>fr. 309, 6,</i> suivre un régime ;<br><b>   II</b> <i>particul. (par une relation d’idées analogue à celle des sens de</i> ἔμπορος) :<br><b>      1</b> voyager pour affaires : χρηματισμοῦ χάριν, PLAT. <i>Leg. 952</i> e, pour affaires de commerce ; εἰς Πόντον, CHION. <i>Ep. 5,</i> dans le Pont ;<br><b>      2</b> <i>p. ext</i>. faire le commerce, trafiquer, THC. <i>7, 13 ;</i> XÉN. <i>Vect. 3, 1 et 3 ; particul</i>. importer, <i>acc</i>. PLAT. <i>Ep. 313</i> e ; DL. <i>7, 2 ;</i> LUC. <i>Nigr. proœm. ;</i><br><b>      3</b> <i>p. ext</i>. gagner par le commerce, <i>acc</i>. SYN. <i>Ep. 4 ;</i><br><b>      4</b> agir en commerçant, <i>particul. en mauv. part, càd</i>. tromper, duper, NT. <i>2Petr. 2, 3 ; en ce sens, act</i>. ἐμπορεύω, POL. <i>38, 4, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. au sens moy</i>. ἐνεπορεύθην ; <i>ao. moy</i>. ἐνεπορευσάμην, PLAT. <i>Ep. 312</i> d.<br><span><b>Étym</b>. ἐν. π.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπορευομαι - ἐμπορεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (2)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1711":"<h1>emporia</h1>\n<p>Strong n° 1711 <i>Prononciation [em-por-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>commerce, marchandise</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμπορία, ας (ἡ) :<br>      1</b> commerce par mer, HÉS. <i>O. 644 ;</i> HDT. <i>3, 139, etc. ;</i> PLAT. <i>Rsp. 371</i> a ; <i>d’où</i> commerce <i>en gén</i>. THC. <i>1, 2 et 7 ;</i> ISOCR. <i>15</i> a, <i>etc. ; au plur</i>. ARSTT. <i>Pol. 4, 4, 10, etc. ;</i><br><b>      2</b> marchandises, XÉN. <i>Vect. 3, 2 ;</i> DÉM. <i>930, 21 ;</i> LYS. <i>908, 10, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. <i>l. c. etc</i>.<br><span><b>Étym</b>. ἔμπορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπορια - ἐμπορία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1712":"<h1>emporion</h1>\n<p>Strong n° 1712 <i>Prononciation [em-por'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un lieu où passent les marchandises, par exemple un port de mer\n<ol type=\"a\">\n<li>un marché, un entrepôt, un magasin, un bazar (Angl. : emporium)</li>\n</ol>\n</li>\n</ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμπόριον, ου (τὸ)</b> <i>v</i>. ἐμπόριος.<br><br>\n<b>ἐμπόριος, α, ον</b>, propre au commerce, <i>d’où subst. :</i><br><b>   I</b> τὸ ἐμπόριον :<br><b>      1</b> place de commerce maritime, HDT. <i>1, 165 ; 4, 108, etc. ;</i> THC. <i>1, 100 ; 7, 50, etc. ;</i> προστάται τοῦ ἐ. HDT. <i>2, 178,</i> préposés de commerce, <i>sorte de consuls maritimes ;</i><br><b>      2</b> <i>particul. à Athènes,</i> Bourse pour le commerce d’exportation, DÉM. <i>923, 4 ;</i><br><b>      3</b> <i>postér</i>. place de commerce, marché dans l’intérieur d’un pays, DH. <i>7, 20 ;</i><br><b>   II</b> τὰ ἐμπόρια, XÉN. <i>Vect. 1, 7 (dout</i>.) les marchandises.<br><span><b><span class=\"arrow\"></span></b> ἐμπόριον, <i>mieux que</i> ἐμπορεῖον <i>non att. (v. Meisterh. p. 42 et note 352</i>).<br><span><b>Étym</b>. ἔμπορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμποριον - ἐμπόριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1713":"<h1>emporos</h1>\n<p>Strong n° 1713 <i>Prononciation [em'-por-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui voyage, que ce soit par mer ou par terre, pour le commerce</li>\n<li>un marchand, par opposition au détaillant ou artisan insignifiant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔμ·πορος, ου (ὁ) :<br>   I</b> <i>subst. :</i><br><b>      1</b> tout homme qui chemine sur (une route) <i>ou</i> dans (un pays) : οἱ ἔμπ. EUR. <i>Alc. 999,</i> les passants ;<br><b>      2</b> passager sur un vaisseau, <i>d’où</i> voyageur, OD. <i>2, 319 ; 24, 300 ; fig</i>. ESCHL. <i>Ch. 661 ;</i><br><b>      3</b> tout voyageur par terre <i>ou</i> par mer, SOPH. <i>O.R. 456 ; O.C. 25, 303 ;</i><br><b>      4</b> <i>particul</i>. voyageur pour affaires de commerce, HDT. <i>2, 39 ;</i> THC. <i>6, 31 ; d’où</i> marchand en gros (<i>p. opp. à</i> κάπηλος) PLAT. <i>Prot. 313</i> d, <i>Rsp. 371</i> d ; <i>fig</i>. PLAT. <i>Soph. 231</i> d ; ANTH. <i>9, 416 ;</i> ἔμπ. βίου, EUR. <i>Hipp. 964,</i> qui trafique de sa vie ;<br><b>   II</b> <i>adj</i>. ναῦς ἔ. DS. <i>5, 12,</i> navire de commerce pour l’exportation.<br><span><b>Étym</b>. ἐν, πορεύομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπορος - ἔμπορος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G1714":"<h1>empretho</h1>\n<p>Strong n° 1714 <i>Prononciation [em-pray'-tho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>brûler</li>\n<li>détruire par le feu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·πίπρημι</b> <span>(<i>impf</i>. ἐνεπίμπρην, <i>f</i>. ἐμπρήσω, <i>ao</i>. ἐνέπρησα, <i>pf</i>. ἐμπέπρηκα ; <i>pass. ao</i>. ἐνεπρήσθην, <i>pf</i>. ἐμπέπρησμαι <i>ou</i> ἐμπέπρημαι)</span> incendier, brûler (une ville, un temple, <i>etc.) acc</i>. HDT. <i>1, 19, etc. ;</i> AR. <i>Nub. 1484 ; avec un dat</i>. πυρὶ ἐμπ. SOPH. <i>Ph. 801,</i> dévorer par le feu ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. ἐμπρήσομαι, <i>ao</i>. ἐνεπρήσαμην)</span> <i>m. sign</i>. HDT. <i>6, 9 ;</i> Q. SM. <i>1, 494, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. pass. part</i>. ἐμπεπρησμένος, HDT. <i>8, 144 ; ou</i> ἐμπεπρημένος (<i>var</i>. -ησμένος) AR. <i>Vesp. 36. Act. fut. épq</i>. ἐνιπρήσω, IL. <i>15, 702. Sur l’orthogr</i>. ἐμπίπρημι, <i>v</i>. ἐμπίπλημι <i>fin</i>.<br><span><b>Étym</b>. ἐν, πίμπρημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπρηθω - ἐμπί(μ)πρημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1715":"<h1>emprosthen</h1>\n<p>Strong n° 1715 <i>Prononciation [em'-pros-then]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en face, devant\n<ol type=\"a\">\n<li>devant, c'est à dire le lieu qui est en face d'une personne ou d'une chose</li>\n<li>devant, en présence, donc opposé à, contre</li>\n<li>devant, à la vue de</li>\n<li>devant, ce qui dénote un rang supérieur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔμ·προσθεν</b>, <i>adv. et prép</i>. en avant, avant :<br><b>      1</b> <i>avec idée de lieu,</i> devant, en avant, <i>abs</i>. HDT. <i>7, 126 ;</i> XÉN. <i>Cyr. 4, 2, 23 ;</i> τὸ <i>ou</i> τὰ ἔμπροσθεν, HDT. <i>5, 62,</i> le devant, le front (d’une troupe, <i>etc</i>.) ; ἐκ τοῦ ἔ. στῆναι, XÉN. <i>Cyr. 2, 2, 6,</i> se tenir en face ; εἰς τὸ ἔ. HDT. <i>4, 61 ; 8, 89,</i> se diriger en avant ; <i>avec un gén</i>. ἔμπρ. τινος, HDT. <i>8, 87,</i> en avant de qqe ch. ; ἔ. τοῦ δικαίου, DÉM. <i>1297, 26,</i> avant la justice, de préférence à la justice ;<br><b>      2</b> <i>avec idée de temps,</i> auparavant : <i>fig</i>. οἱ ἔμπροσθεν, PLAT. <i>Pol. 296</i> a, les ancêtres ; ὁ ἔμπροσθεν χρόνος, XÉN. <i>Mem. 4, 8, 2,</i> le temps antérieur ; <i>avec le gén</i>. τὰ ἔ. τούτων ῥηθέντα, PLAT. <i>Leg. 773</i> e, les choses dites auparavant ; ἑτέρη γνώμη ἔ. ταύτης, HDT. <i>7, 144,</i> l’autre avis antérieur à celui-ci ; ἔμπροσθεν εἶναι τῶν πραγμάτων, DÉM. <i>51, 15,</i> devancer les événements, les prévenir pour les diriger.<br><span><b>Étym</b>. ἐν, πρόσθεν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπροσθεν - ἔμπροσθεν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 44 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (18)</li>\n<li>Marc (2)</li>\n<li>Luc (10)</li>\n<li>Jean (5)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (4)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G1716":"<h1>emptuo</h1>\n<p>Strong n° 1716 <i>Prononciation [emp-too'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>cracher sur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·πτύω :<br>      1</b> cracher dans, <i>avec</i> ἐς <i>et l’acc</i>. HDT. <i>1, 138 ;</i><br><b>      2</b> cracher sur : εἴς τι, ATH. <i>345</i> c, sur qqe ch. ; εἴς τινα, NT. <i>Matth. 27, 30 ;</i> τινί, ARSTT. <i>fr. 271,</i> sur qqn ; τινὶ εἰς τὸ πρόσωπον, PLUT. <i>M. 189</i> a, au visage de qqn ; <i>au pass</i>. être couvert de crachats, être conspué, MUSON. (STOB. <i>Fl. 19, 16</i>) ;<br><b><i>Moy.</i></b> cracher sur (qqn) SPT. <i>Num. 25, 9</i>.<br><span><b>Étym</b>. ἐν, πτ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμπτυω - ἐμπτύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1717":"<h1>emphanes</h1>\n<p>Strong n° 1717 <i>Prononciation [em-fan-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se manifester\n<ol type=\"a\">\n<li>fig. de Dieu donnant des preuves du salut par sa grâce et ainsi se manifestant lui-même</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·φανής, ής, ές</b> <span>[ᾰ]</span><br><b>   I</b> qui montre en soi, qui réfléchit (une image) <i>en parl. d’un miroir,</i> PLAT. <i>Tim. 46</i> a ;<br><b>   II</b> qui apparaît, <i>d’où :</i><br><b>      1</b> qui se montre aux regards, qui se rend visible, <i>en parl. des dieux, des formes vues en songe, etc</i>. SOPH. <i>O.R. 909 ;</i> EUR. <i>Bacch. 22 ;</i> PLAT. <i>2 Alc. 141</i> a ; <i>en parl. de choses,</i> visible, manifeste ; τὴν διάνοιαν ἐμφανῆ ποιεῖν διὰ τῆς φωνῆς, PLAT. <i>Theæt. 206</i> d, rendre sa pensée visible au moyen de la parole ; ἐμφ. τεκμήρια, SOPH. <i>El. 1109,</i> preuves visibles ; οὐ γὰρ ἔστι τἀμφανῆ κρύπτειν, SOPH. <i>O.C. 755,</i> car il n’est pas possible de cacher ce qui est visible pour tous ; ποιεῖν τι ἐμφανές, HDT. <i>1, 203 ; 3, 101,</i> faire qqe ch. au grand jour, en public ; ἐμφανῶν κατάστασις, DÉM. <i>1251, 3 ;</i> IS. <i>59, 22,</i> démonstration d’une chose par la production des preuves, par l’évidence ;<br><b>      2</b> qui se fait sous les yeux de tous, en public ; ἐμφανές ἐστιν ὅτι, XÉN. <i>Hier. 9, 10,</i> il est visible que, <i>etc. ;</i> τὸ ἐμφανές, DÉM. <i>1283, 16,</i> le grand jour ; εἰς τοὐμφανὲς ἰέναι, XÉN. <i>Mem. 4, 3, 13,</i> aller au grand jour ; ἐκ τοῦ ἐμφανοῦς, XÉN. <i>Cyr. 1, 6, 41 ;</i> ἐκ τοῦ ἐμφανέος (<i>ion</i>.) HDT. <i>3, 150, etc. ;</i> ἐν τῷ ἐμφανεῖ, THC. <i>2, 21 ;</i> XÉN. <i>An. 2, 5, 25,</i> au grand jour, publiquement ;<br><b>      3</b> <i>p. suite,</i> évident, non dissimulé : βία ἐμφ. THC. <i>4, 86,</i> violence manifeste, force ouverte ; ἐμφ. λόγος, THC. <i>7, 48,</i> parole non déguisée, déclaration nette ;<br><b>      4</b> connu de tous, HDT. <i>2, 33 ;</i> SOPH. <i>Ant. 448 ; d’où, en parl. de pers</i>. qui est en évidence, connu, DS. <i>1, 68</i>.<br><span>•<i> Cp</i>. -έστερος, ESCHL. <i>Ch. 818</i>. <i>• Sup</i>. -έστατος, XÉN. <i>Mem. 3, 8, 10 ;</i> TH. <i>H.P. 1, 14, 4 ; 4, 8, 4 ; C.P. 6, 3, 4 ;</i> PLUT. <i>M. 108</i> e.<br><span><b>Étym</b>. ἐν, φαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμφανης - ἐμφανής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G1718":"<h1>emphanizo</h1>\n<p>Strong n° 1718 <i>Prononciation [em-fan-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>manifester, exposer à la vue</li>\n<li>se montrer, venir à la vue, apparaître, être manifesté</li>\n<li>indiquer, révéler, déclarer, faire connaître</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμφανίζω</b> <span>(<i>f</i>. ιῶ, <i>ao</i>. ἐνεφάνισα, <i>pf. inus</i>.)</span> <span>[ᾰ]</span> rendre visible, <i>d’où :</i><br><b>      1</b> faire apparaître, faire voir, produire : τινά, EUR. <i>fr. 794,</i> qqn ; <i>au pass</i>. devenir visible, apparaître, DL. <i>1, 7 ;</i><br><b>      2</b> faire voir clairement, PLAT. <i>Soph. 244</i> a ; ἐμφ. τινί τι, XÉN. <i>Mem. 4, 3, 4,</i> qqe ch. à qqn ; ἐμφ. ὅτι, XÉN. <i>Cyr. 8, 1, 26,</i> montrer que, <i>etc. ; avec un part</i>. οὐκ οὖσαν ἀγαθὸν τὴν ἡδονήν, ARSTT. <i>Nic. 10, 3, 11,</i> montrer clairement que le plaisir n’est pas un bien ; ἐμφ. ἑαυτόν, POL. <i>30, 17, 2 ;</i> ATH. <i>37</i> e, exposer son sentiment ;<br><b>      3</b> représenter : τινὰ φίλον, DÉM. <i>188, 13,</i> qqn comme son ami ; <i>cf</i>. XÉN. <i>Ages. 1, 12 ;</i><br><b>      4</b> déclarer, signifier : τινὶ ποιεῖν τι, POL. <i>6, 35, 8,</i> à qqn de faire qqe ch.<br><span><b>Étym</b>. ἐμφανής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμφανιζω - ἐμφανίζω</font>\n<br><br>Voir définition \n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (2)</li>\n<li>Actes (5)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G1719":"<h1>emphobos</h1>\n<p>Strong n° 1719 <i>Prononciation [em'-fob-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>jeté dans la crainte, terrifié, effrayé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔμ·φοϐος, ος, ον :<br>      1</b> <i>act</i>. qui inspire la crainte, terrible, SOPH. <i>O.C. 39 ;</i><br><b>      2</b> <i>pass</i>. épouvanté, craintif, SPT. <i>Sir. 19, 24</i>.<br><span><b>Étym</b>. ἐν, φέϐομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμφοβος - ἔμφοβος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1720":"<h1>emphusao</h1>\n<p>Strong n° 1720 <i>Prononciation [em-foo-sah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>souffler ou respirer sur, ou dans, ou en</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐμ·φυσάω-ῶ</b> <span>[ῡ]</span><br><b>      1</b> souffler dans <i>ou</i> sur : ἔς τι, dans qqe ch. : τινί <i>ou</i> εἴς τινα, sur qqn ; <i>abs</i>. souffler dans une flûte, AR. <i>Vesp. 1219 ;</i><br><b>      2</b> enfler, gonfler, ARSTT. <i>Probl. 5, 9 ; au pass</i>. être enflé <i>ou</i> gonflé, HPC. <i>Coac. 143 ;</i> ARSTT. <i>H.A. 4, 1, 12, etc. ; fig</i>. être enflé d’orgueil, CLÉARQ. (ATH. <i>255</i> d).<br><span><b>Étym</b>. ἐν, φ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμφυσαω - ἐμφυσάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1721":"<h1>emphutos</h1>\n<p>Strong n° 1721 <i>Prononciation [em'-foo-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>implanté par la nature, planté par d'autres moyens</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔμφυτος, ος, ον</b> <span>[ῠ]</span> implanté, <i>d’où</i> inné, naturel, <i>en parl. du sang paternel,</i> SOPH. <i>O.C. 1671 ;</i> τὸ ἐμφ. θερμόν, HPC. <i>1243,</i> la chaleur naturelle ; ἐμφ. ἡ ἀρετή, PLAT. <i>Eryx. 398</i> c, la vertu est innée dans l’homme, <i>p. opp. à</i> διδακτός ; <i>avec un dat</i>. ἔρως ἔμφ. τοῖς ἀνθρώποις, PLAT. <i>Conv. 191</i> c, l’amour est inné chez l’homme ; <i>joint à</i> πάτριος, DÉM. <i>295, 25</i>.<br><span><b>Étym</b>. ἐμφύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εμφυτος - ἔμφυτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1722":"<h1>en</h1>\n<p>Strong n° 1722 <i>Prononciation [en]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Dans son sens premier : dans, à l'intérieur de. Le datif qui accompagne εν remplace un ancien locatif.\n<ol><li>en, par, avec, etc.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἐν</b> (<i>poét</i>. <b>ἐνί</b>, <i>épq</i>. <b>εἰν</b>) <i>adv. et prép</i>. dedans, dans, en. ;<br><b><i>Adv.</i></b> dedans :<br><b>   I</b> <i>avec un verbe s.-e. :</i> ἐν δὲ ἴα ψυχή, IL. <i>21, 569,</i> dedans, <i>càd</i>. (en lui) il n’y a qu’une âme ; ἐν μὲν γὰρ λειμῶνες,… ἐν δ' ἄροσις λείη, OD. <i>9, 132,</i> dedans, <i>càd</i>. (dans cette terre) il y a des prairies, (dans cette terre) aussi le labour serait facile, <i>etc. ;</i> πολέες δ' ἔνι μῦθοι παντοῖοι, IL. <i>20, 248,</i> et il y a dedans, (<i>càd</i>. en elle) bien des paroles de toute sorte ; <i>cf</i>. IL. <i>5, 740 ;</i> OD. <i>9, 126, etc. ; — avec un verbe s.-e. et un dat. avant</i> ἐν : ἐπεὶ οὔ οἱ ἔνι φρένες, IL. <i>14, 141,</i> car dedans (<i>càd</i>. en lui) il n’(y) a point de cœur ; <i>cf</i>. OD. <i>18, 335, etc. ;</i><br><b>   II</b> <i>avec un verbe sans rég., au sens de :</i><br><b>      1</b> dedans : ἐν δ' ἄνδρες ναίουσι, IL. <i>9, 154,</i> dedans (<i>càd</i>. dans ces villes) habitent des hommes (riches en troupeaux, <i>etc</i>.) ; ἐν δὲ θρόνοι ἐρηρέδατο, OD. <i>7, 95,</i> dedans (<i>càd</i>. dans la cour) étaient fixés des trônes ; ἐν δ' αἶγες γεγάασιν, OD. <i>9, 118,</i> dedans (<i>càd</i>. dans ce pays) naissent des chèvres, <i>etc. ; cf</i>. IL. <i>9, 296 ;</i> OD. <i>1, 51, etc. ;</i> ἐν δ' ἄλοχοι ἐπιστενάχουσιν, SOPH. <i>O.R. 183,</i> et dedans (<i>càd</i>. dans les temples), de jeunes épouses gémissent (sur ces malheurs) ; <i>cf</i>. SOPH. <i>O.R. 27, Aj. 675, etc. ;</i><br><b>      2</b> parmi : ἐν δ' αὐτὸς ἀριστεύεσκε, IL. <i>16, 551,</i> et parmi (eux) il était le plus brave ;<br><b>      3</b> <i>avec idée de temps,</i> en ce temps, cependant, <i>d’ord. avec</i> δέ (ἐν δέ) ESCHL. <i>fr. 304, 4 ;</i> SOPH. <i>Ant. 420, Tr. 206 ;</i><br><b>   III</b> <i>avec un verbe accompagné d’un dat. de lieu ou de personne, au sens de :</i><br><b>      1</b> dans : ἐν δέ τε θυμὸς στήθεσιν ἄτρομός ἐστι, IL. <i>16, 162,</i> et en (lui) dans sa poitrine est un cœur qui ne tremble pas ; ἐν δέ τε οἶνον κρητῆρσιν κερόωντο, OD. <i>20, 252,</i> et dedans, au fond des cratères, ils mélangeaient le vin ;<br><b>      2</b> parmi : ἐν δὲ γέλως ὦρτο θεοῖσιν, OD. <i>8, 343,</i> et parmi (les dieux) un rire s’éleva ;<br><b>   IV</b> <i>avec un verbe accompagné d’un dat. d’attribution :</i> ἐν δέ οἱ ἀσκὸν ἔθηκε, OD. <i>5, 265,</i> et dedans (<i>càd</i>. dans le navire) elle plaça pour lui une outre ;<br><b>   V</b> <i>avec un verbe accompagné d’un double dat. de lieu et d’attribution :</i> ἐν δέ μοι ἄλφιτα χεῦον δοροῖσιν, OD. <i>2, 354,</i> verse-moi aussi de la farine dans des outres ;<br><b><i>Prép. avec le dat. :</i></b> dans :<br><b>A</b> (<i>avec idée de lieu</i>) :<br><b>   I. 1</b> <i>avec un dat. de lieu sans mouv. :</i> τίς ἔνδον ἐν δόμοις ; ESCHL. <i>Ch. 654,</i> y a-t-il quelqu’un dans la maison ? ἐν τῇδε τῇ πόλει, PLAT. <i>Prot. 339</i> c, dans cette ville-ci ; <i>avec un n. de ville ou de pays :</i> ἐν Ἀθήναις, IL. <i>2, 549,</i> dans Athènes, à Athènes ; ἐν Τροίῃ, IL. <i>2, 162,</i> dans la Troade ; <i>dans la prose att</i>. ἐν <i>ne se rencontre dev. un n. de ville, dans les inscript., qu’à partir de 315 av. J.C. :</i> ἐν Ἐλευσῖνι <i>(315 et 307/286, etc. av. J.C.), cf</i>. CIA. <i>2, 467, 11 et 28 (100 av. J.C.), etc</i>. à Éleusis ; ἐμ Μαραθῶνι, CIA. <i>2, 601, 21 (après 300 av. J.C.)</i> à Marathon, <i>v. Meisterh. p. 170 au commenc. ; le plus souv</i>. ἐν <i>dev. un n. de lieu signifie, dans les écriv. class. Thucydide, Xénophon, etc</i>. « dans la région de, près de », <i>etc. ; v. ci-dessous ; — par ellipse, avec un gén. (s.-e</i>. οἴκῳ, δόμοις, <i>etc.) : avec un n. de pers. :</i> ἐν Ἀλκινόοιο, OD. <i>7, 132,</i> dans (le palais) d’Alkinoos ; ἐνὶ Κίρκης, OD. <i>10, 282,</i> dans (le palais) de Circè ; εἰν Ἀΐδαο, IL. <i>22, 389 ;</i> ἐν Ἅιδου, ATT. (<i>v</i>. Ἅιδης), dans (le séjour) d’Hadès ; ἐν Πυθίου, THC. <i>6, 54,</i> dans (le temple) d’Apollon Pythien ; <i>avec un n. commun :</i> ἐν ἀφνειοῦ πατρός, IL. <i>6, 47,</i> dans (le palais) de mon père riche en biens ; ἐν διδασκάλων, PLAT. <i>1 Alc. 110</i> a, à l’école ; ἐν αὑτοῦ, AR. <i>Vesp. 642 ;</i> PLAT. <i>Charm. 155</i> d, dans sa propre maison, chez soi <i>(cf</i>. εἰς <i>avec une construct. analogue) ; dans les inscr. att., de même avec un n. propre de pers</i>. ἐμ Πανδίονος, CIA. <i>2, 553, 8 (403 av. J.C</i>.) dans (le temple) de Pandion ; ἐν Διονύσου, CIA. <i>2, 420, 5 (commenc. du 2<sup>e</sup> siècle av. J.C.)</i> dans (le temple) de Dionysos ; <i>avec un n. de dème :</i> ἐν Δημοτιωνιδῶν, CIA. <i>2, add. 841, b, 21 (396 av. J.C</i>.) ; ἐν Ἡφαιστιαδῶν, CIA. <i>2, 772, b, 12 (4<sup>e</sup>/3<sup>e</sup> siècle av. J.C.) ; etc</i>. dans le dème de Dèmotiônides ; dans le dème d’Hèphæstiades (<i>v. Meisterh. p. 175, 19, etc</i>.) ;<br><b>      2</b> <i>avec un dat. de lieu, après un verbe ou un subst. de mouv., mais impliquant une idée de permanence dans le lieu indiqué par</i> ἐν : πίπτειν ἐν κονίῃσι, IL. <i>4, 482, etc. ;</i> OD. <i>10, 282,</i> tomber (et rester étendu) dans la poussière ; ἐμπεσεῖν ἐν ὕλῃ, IL. <i>11, 155,</i> s’abattre sur une forêt (et s’y propager), <i>en parl. d’un incendie ;</i> λεὼν ἐν βουσὶ θορών, IL. <i>5, 161,</i> un lion s’étant élancé au milieu d’un troupeau de bœufs ; ἐν χείρεσσι λάϐ' αἰγίδα, IL. <i>15, 229,</i> prends l’égide dans tes mains ; ἂν δ' ἔϐαν ἐν δίφροισι, IL. <i>23, 132,</i> ils montèrent (et se tinrent) dans le char ; ἡ ἐν τῷ Πειραιῷ τῶν νεῶν καταφυγή, THC. <i>8, 11,</i> la retraite des navires réfugiés à Peiræôs ; ὁ ἐν Σικελίᾳ πλοῦς, LYS. <i>19, 43 Baiter-Sauppe,</i> l’expédition navale pour la (campagne de) Sicile ; <i>particul. avec les verbes signifiant</i> verser, poser : οἶνον ἔχευεν ἐν δέπαϊ χρυσέῳ, OD. <i>20, 261,</i> il versait du vin que recueillait une coupe d’or ; ἐν τάφῳ θεῖναι, SOPH. <i>Ant. 499,</i> déposer dans un tombeau ; <i>de même dans les inscr. att. où</i> θεῖναι <i>et</i> καταθεῖναι <i>se construisent qqf. avec</i> ἐν : CIA. <i>1, 32, a, 30 (435/420 av. J.C.) ; 2, 115, 21 (343 av. J.C.) v. Meisterh. p. 176, 20 ; l’idée d’immobilité finale qu’implique cette construct. est qqf. directement indiquée par un pf. :</i> ἐν τῇ γῇ καταπεφευγέναι, THC. <i>4, 14,</i> s’être réfugiés à terre ; ᾤχοντο δὲ ἐν τοῖς ὀχυροῖς καὶ τὰ ἐπιτήδεια ἐν τούτοις ἀνακεκομισμένοι ἦσαν, XÉN. <i>An. 4, 7, 17,</i> ils s’étaient retirés dans les lieux fortifiés et y avaient monté et déposé les approvisionnements nécessaires ;<br><b>      3</b> <i>poét. avec un dat. du lieu en un sens de direction et de mouv., c. syn. de</i> εἰς, <i>seul. en poés</i>. PD. <i>P. 2, 11 et 86 ; 5, 38 ; N. 7, 31 ;</i><br><b>   II</b> <i>(avec l’idée d’un lieu déterminé et des environs immédiats) d’où :</i><br><b>      1</b> dans la région de : ἐν Κύπρῳ ναυμαχέειν, HDT. <i>5, 115,</i> livrer un combat naval dans (les eaux de) Chypre ; τότε τὴν ἐν Νοτίῳ ἐνίκησε ναυμαχίαν, XÉN. <i>Hell. 2, 1, 6,</i> (Lysandre) fut vainqueur alors à la bataille de Notion ; μάχη ἐγεγόνει ἐν τῇ Ποτιδαίᾳ, PLAT. <i>Charm. 153</i> b, on avait livré combat à Potidée ;<br><b>      2</b> auprès de, au bord de : ἐν ποταμῷ, IL. <i>18, 521 ;</i> OD. <i>5, 466,</i> au bord du fleuve ;<br><b>   III</b> <i>avec l’idée d’un lieu qui entoure, d’où</i> au milieu de : οὐρανὸς ἐν αἰθέρι καὶ νεφέλῃσι, IL. <i>15, 192,</i> le ciel au milieu de l’éther et des nuages ; <i>p. anal., avec l’idée d’un objet</i> (instrument, objet quelconque <i>ou</i> organe naturel) <i>qui entoure, saisit ou contient, particul. :</i><br><b>      1</b> <i>en parl. d’armures, de vêtements, de fardeaux, etc. :</i> ἐν ὅπλοις παρεῖναι, XÉN. <i>Ages. 1, 33, ou</i> εἶναι, HDT. <i>1, 13 ;</i> THC. <i>6, 74,</i> se tenir <i>ou</i> être sous les armes ; χαλκέοισι ἐν ἔντεσι, PD. <i>O. 4, 22,</i> (être) revêtu d’une armure d’airain ; ἐν ἐσθῆσι, HDT. <i>2, 159,</i> (être) enveloppé de vêtements ; ἐν μεγάλοις φορτίοις τρέχειν, XÉN. <i>Cyr. 2, 3, 14,</i> courir chargé de grands fardeaux ; ἐν πώγωνι βαθεῖ, LUC. <i>Salt. 5,</i> avec (<i>litt</i>. dans) une barbe épaisse ;<br><b>      2</b> <i>en parl. d’un instrument proprement dit :</i> ἐν δεσμῷ δῆσαι, IL. <i>5, 386 ;</i> OD. <i>12, 54,</i> enfermer (<i>litt</i>. lier) dans un lien ; ἐν πέδαις δεδέσθαι, XÉN. <i>An. 4, 3, 8,</i> être lié dans des entraves ; κἄζευξα πρῶτος ἐν ζυγοῖσι κνώδαλα, ESCHL. <i>Pr. 462,</i> c’est moi aussi qui le premier ai retenu le bétail (bœufs, ânes, mules) au joug ; πίνειν ἐν ποτηρίῳ, LUC. <i>D. deor. 6, 2,</i> boire dans une coupe : ἐν ἀργύρῳ πίνειν, LUC. <i>M. cond. 26,</i> boire dans un vase d’argent, <i>etc. ;</i><br><b>      3</b> <i>en parl. des mains ou des bras :</i> ἐν χεροῖν λαϐεῖν, SOPH. <i>O.R. 912,</i> prendre dans ses mains ; ἐν ξέναισι χερσὶ κηδευθείς, SOPH. <i>El. 1141,</i> ce sont des mains étrangères qui t’ont rendu les derniers devoirs ; κοὔτ' ἐν φίλαισι χερσὶν ἐκόσμησα, SOPH. <i>El. 1138</i> d, je ne t’ai pas, de mes mains, rendu les derniers devoirs ; <i>en parl. de combats :</i> γενομένης δ' ἐν χερσὶ τῆς μάχης, THC. <i>6, 70,</i> comme on en était venu aux mains ; ἦν ἡ μάχη κρατερὰ καὶ ἐν χερσὶ πᾶσα, THC. <i>4, 43,</i> le combat était fortement engagé et d’homme à homme sur toute la ligne ;<br><b>      4</b> <i>p. ext. en parl. d’autres organes :</i> ἐν ὠσὶ νωμῶν καὶ φρεσίν, φάους δίχα, ESCHL. <i>Sept. 25,</i> (le devin aveugle Tirésias), ce pâtre des oiseaux, qui observe (les augures) avec les oreilles et l’intelligence, sans la lumière des yeux ; ἐν ὀφθαλμοῖσιν ὁρᾶσθαι, IL. <i>3, 306 ;</i> ἐν ὀφθαλμοῖσι ἰδέσθαι, OD. <i>10, 385 ;</i> SOPH. <i>Ant. 760,</i> voir avec ses yeux ; ἐν ὄψει διαγιγνώσκειν, ἐν ἀκοῇ, PLAT. <i>Theæt. 206</i> a, discerner avec la vue, avec l’ouïe ;<br><b>      5</b> <i>en parl. d’un instrument ou d’un moyen qqconque ; fig</i>. ἐν λιταῖς, SOPH. <i>Ph. 60,</i> au moyen de prières, par des prières ; ἐν δόλῳ, SOPH. <i>Ph. 102,</i> par ruse ; ἐν λόγοις, SOPH. <i>Ant. 961, 1003 ; Tr. 886 ; Ph. 1393,</i> par des paroles (persuader, <i>etc</i>.) ;<br><b>      6</b> <i>fig. en parl. des conditions (matérielles ou morales) au milieu desquelles on se trouve :</i> ἐνὶ πολέμῳ, IL. <i>4, 258,</i> dans la guerre ; ἐν φιλοσοφίᾳ εἶναι, PLAT. <i>Phæd. 59</i> a, être engagé dans l’étude de la philosophie ; οἱ ἐν τοῖς πράγμασι, THC. <i>3, 28,</i> ceux qui sont aux affaires ; οἱ ἐν τέλει, THC. <i>7, 73,</i> ceux qui sont en charge, les magistrats ; ἐν ἀφθόνοις βιοτεύειν, XÉN. <i>An. 3, 2, 25,</i> vivre dans l’abondance ; <i>en parl. de sentiments :</i> ἐν πένθεϊ, dans le deuil ; ἐν δοιῇ, IL. <i>22, 483,</i> dans le doute ; ἐν ὀργῇ ἔχειν τινά, THC. <i>2, 21,</i> être irrité <i>ou</i> indigné contre qqn ; ἐν αἰτίᾳ ἔχειν τινά, HDT. <i>5, 106,</i> accuser qqn, <i>litt</i>. avoir qqn en état d’accusation ; ἐν αἰτίᾳ εἶναι, XÉN. <i>Mem. 2, 8, 6,</i> être exposé à des reproches ; ἐν <i>forme ainsi avec des adjectifs ou des substantifs un grand nombre de locut. adv</i>. ἐν βραχεῖ = βραχέως, SOPH. <i>El. 673,</i> brièvement ; ἐν τάχει = ταχέως, SOPH. <i>O.R. 865,</i> promptement ; ἐν ἀσφαλεῖ = ἀσφαλῶς, EUR. <i>I.T. 762,</i> en sûreté ; ἐν ὁμοίῳ = ὁμοίως, THC. <i>2, 53,</i> semblablement, également ; <i>rar. avec un adj. plur</i>. ἐν ἀργοῖς = ἀργῶς, SOPH. <i>O.R. 287,</i> laisser qqe ch. dans l’inaction, <i>càd</i>. sans le faire ; ἐν κενοῖς = κενῶς, SOPH. <i>Aj. 971,</i> à vide, vainement ; <i>avec un subst</i>. ἐν δίκῃ = δικαίως, SOPH. <i>Tr. 1069, etc</i>. justement ;<br><b>      7</b> dans les limites de, <i>d’où</i> en se restreignant dans, en se réglant sur, en se conformant à ; <i>p. suite,</i> selon, d’après : ἐν τοῖς ὁμοίοις νόμοις ποιεῖν τὰς κρίσεις, THC. <i>1, 77,</i> instituer des jugements d’après des lois régissant également les deux parties en cause ; σημαίνειν ἐν οἰωνοῖς, XÉN. <i>Cyr. 8, 7, 3,</i> donner des avis par des augures, <i>en parl. des dieux ;</i> τὰ πραχθέντα… ἐν ἐπιστολαῖς ἴστε, THC. <i>7, 11,</i> les faits antérieurs, vous les connaissez par des lettres (<i>litt</i>. pour en avoir lu l’exposé dans des lettres) ;<br><b>      8</b> dans les attributions de, au pouvoir de : δύναμις γὰρ ἐν ὑμῖν, OD. <i>10, 69,</i> car vous en avez le pouvoir ; ταῦτα δ' ἐν τῷ δαίμονι, SOPH. <i>O.C. 1443,</i> ces choses sont au pouvoir de la divinité ; ἐν τῷ θεῷ τὸ τέλος ἦν, οὐκ ἐν ἐμοί, DÉM. <i>292, 21,</i> c’était de la divinité, non de moi, que dépendait l’issue de l’événement ; ἔν σοι πάντα ἐστί, XÉN. <i>Œc. 7, 14,</i> tout dépend de toi ; ἐν ταῖς ναυσὶ τῶν Ἑλλήνων πράγματα ἐγένετο, THC. <i>1, 74,</i> le salut des Grecs reposait sur leurs vaisseaux ;<br><b>      9</b> en ce qui regarde, eu égard à : <i>avec un rég. de chose :</i> ἐν πάντεσσ' ἔργοισι δαήμων, IL. <i>23, 671,</i> habile en toute sorte de travaux ; κρείσσων ἐν κυναγίαις, EUR. <i>Bacch. 339,</i> (parce qu’il s’était vanté d’être) plus habile chasseur ; ἡ ἐν ὅπλοις μάθησις, PLAT. <i>Lach. 190</i> d, l’éducation (d’Artémis) pour apprendre le maniement des armes ; <i>avec un rég. de pers</i>. ἐν ἐμοὶ θρασύς, SOPH. <i>Aj. 1315,</i> hardi envers moi :<br><b>      10</b> <i>avec un plur</i>. au milieu de, parmi : οἴη ἐν ἀθανάτοισιν, IL. <i>1, 398,</i> seule parmi les immortels ; ταῦτα νόμιμα ἦν ἐν Μήδοις, XÉN. <i>Cyr. 1, 3, 2,</i> c’étaient là choses en usage parmi les Mèdes ; ὄνομα μέγιστον ἐν πᾶσιν ἀνθρώποις ἔχειν, THC. <i>2, 64,</i> avoir une très grande renommée parmi tous les hommes ; Κῦρος εὐκλεεῖς ὑμᾶς ἐν πᾶσιν ἀνθρώποις ἐποίησεν, XÉN. <i>Cyr. 8, 5, 23,</i> Cyrus vous a rendus célèbres parmi tous les hommes ; φῦλον ἐν ἀνθρώποισι ματαιότατον, PD. <i>P. 3, 21,</i> la race la plus vaine parmi les hommes ; <i>particul. dans la loc</i>. ἐν τοῖς <i>avec</i> πρῶτοι <i>ou avec un superl</i>. ἐν τοῖς πρῶτοι Ἀθηναῖοι τὸν σίδηρον κατέθεντο, THC. <i>1, 6,</i> les Athéniens furent les premiers à déposer le fer ; τοῦτό μοι ἐν τοῖσι θειότατον φαίνεται γενέσθαι, HDT. <i>7, 137,</i> c’est ce qui rend évident pour moi qu’il y a dans cet événement une des preuves les plus certaines de la volonté divine ; ἐν τοῖς πλεῖσται δὴ νῆες, THC. <i>3, 17,</i> l’une des flottes les plus nombreuses ; ἐν τοῖς μάλιστα, <i>litt</i>. parmi ceux qui le sont le plus (<i>v</i>. μάλιστα). <i>Par suite, lorsqu’il s’agit d’un orateur, d’un accusé,</i> ἐν <i>correspond au franç</i>. devant : ἐν ὑμῖν ἐρέω, IL. <i>9, 528,</i> je dirai au milieu de vous, <i>càd</i>. devant vous ; λέγειν ἐν ὑμῖν, XÉN. <i>An. 5, 7, 10,</i> parler devant vous ; λέγειν ἐν τῷ δήμῳ, PLAT. <i>Rsp. 565</i> b, parler devant le peuple ; λέγειν ἐν τοῖς δικασταῖς, ANT. <i>6, 23 Baiter-Sauppe,</i> parler devant les juges ; <i>p. anal</i>. ἐν ἐμοί, SOPH. <i>O.C. 1214,</i> devant moi (faisant fonction de juge), <i>càd</i>. si l’on s’en rapporte à moi ; ἐν θεοῖς, SOPH. <i>Ant. 923,</i> devant les dieux, aux yeux des dieux ; <i>de même</i> τἀν ποσὶν κακά, SOPH. <i>Ant. 1327,</i> les maux qui sont entre les pieds, <i>ou</i> devant les pieds, <i>càd</i>. les maux présents ;<br><b>   IV</b> <i>avec idée d’une surface,</i> dans <i>au sens du franç</i>. sur : ἐν θρόνοισι, OD. <i>8, 422,</i> sur des trônes ; ἥμενοι ἐν ῥινοῖσι, OD. <i>1, 108,</i> assis sur des peaux (de bœufs) ; οὔρεος ἐν κορυφῇσ', IL. <i>2, 456,</i> sur les sommets d’une montagne ; χιὼν κατατήκετ' ἐν ὄρεσσιν, OD. <i>19, 205,</i> la neige fond sur les montagnes ; ἐν θαλλοῖς συγκατῄθομεν, SOPH. <i>Ant. 1201,</i> nous brûlions (les restes du corps) sur un amas de rameaux (verts) ; ἐν πέτροισι πέτρον ἐκτρίϐων, SOPH. <i>Ph. 295,</i> faisant jaillir (la flamme) en frottant des cailloux l’un contre l’autre ; <i>particul. dans la loc. homér</i>. θεῶν ἐν γούνασι κεῖται, IL. <i>17, 514,</i> (cela) est sur les genoux des dieux, <i>càd</i>. dépend de la volonté des dieux ;<br><b>B</b> (<i>avec idée de temps</i>) :<br><b>   I</b> dans, en, au temps de, au moment de ; ἐν τούτῳ τῷ χρόνῳ, XÉN. <i>An. 4, 2, 17 ; ou simpl</i>. ἐν τούτῳ, HDT. <i>1, 126, etc</i>. en ce temps-là ; ἐν ᾧ (<i>s.-e</i>. χρόνῳ) HDT. <i>6, 89,</i> dans le temps que ; ἐν ᾧ…, ἐν τούτῳ, XÉN. <i>Hell. 5, 2, 29,</i> pendant que…, pendant ce temps ; ὥρῃ ἐν εἰαρινῇ, IL. <i>16, 643,</i> dans la saison printanière ; ἐν ταῖς σπονδαῖς, XÉN. <i>An. 3, 1, 1,</i> au moment du traité ; ἐν τῇ ἑορτῇ, THC. <i>7, 73,</i> au moment de la fête ;<br><b>   II</b> pendant la durée de, pendant, durant : ἐν ἔτεσι πεντήκοντα, THC. <i>1, 118,</i> en cinquante ans ; ἐν τρισὶ μησί, XÉN. <i>Hell. 1, 1, 37,</i> en trois mois ; ἣν ἐνιαυσίαν ὁδὸν ὁ βάρϐαρος ἐποιήσατο, ταύτην μεῖον ἢ ἐν μηνὶ κατήνυσεν ὁ Ἀγησίλαος, XÉN. <i>Ages. 2, 1,</i> le chemin que le barbare (Xerxès) avait mis un an à faire, Agésilas le parcourut complètement en moins d’un mois ; <i>de même, dans les inscr. att</i>. ἐν τρισὶν ἡμέραις, CIA. <i>2, add. 834, c, 67 (après 329 av. J.C</i>.) en trois jours (<i>v. Meisterh. p. 167, 14</i>) ;<br><b>C</b> <i>avec idée de nombre,</i> en : ἐν δυσὶ σταδίοις, DS. <i>20, 74,</i> en deux stades ;<br><b>Syntaxe :</b> ἐν <i>se place d’ord. devant son rég. (v. ci-dessus) ; en poésie, on le trouve qqf. après son rég. entre le subst. et l’adj. qui accompagne ce dernier :</i> φυλάκεσσιν ἐν ἀγρομένοισι, IL. <i>10, 180 ; cf. 16, 643 ;</i> THCR. <i>Idyl. 9, 26 ; 13, 43, etc. ; ou entre l’adj. et le subst</i>. THCR. <i>Idyl. 9, 16 ; 13, 40 ; 16, 43 ; qqf. abs. après son rég</i>. IL. <i>9, 382 ;</i> OD. <i>4, 127 ; 12, 103 ;</i> A. RH. <i>4, 546 ;</i> THCR. <i>Epigr. 13, 3, etc. ; surtout</i> ἐνί <i>qui s’écrit alors</i> ἔνι, IL. <i>7, 221 ;</i> OD. <i>5, 57, etc. Il est qqf. séparé de son rég. par qqes mots,</i> OD. <i>11, 115 ;</i> HDT. <i>6, 69 ;</i> SOPH. <i>O.R. 34, etc. ;</i> THCR. <i>Idyl. 16, 34 ; 17, 17, etc</i>.<br><i>En compos. il signifie :</i><br><b>      1</b> dans (<i>v</i>. ἐνοράω, ἐνδέω, ἔναιμος, ἔμφωνος, <i>etc</i>.) ; ;<br><b>      2</b> devant (<i>v</i>. ἐνδείκνυμι, ἐγγελάω, ἐνυϐρίζω, <i>etc</i>.) ; ;<br><b>      3</b> <i>qqf., avec un adj., en un sens d’atténuation,</i> quelque peu (<i>v</i>. ἔμπικρος, ἔνσιμος, <i>etc</i>.) ; ;<br><b>      4</b> dans les limites de, dans la mesure de, conformément à (<i>v</i>. ἔννομος).<br><i>En compos. et, dans les inscr., d’un mot à un autre,</i> ἐν <i>devient :</i><br><b>      1</b> ἐμ <i>devant</i> β, π, φ, μ, ψ : ἐμϐαίνω, ἐμ Βρέᾳ, CIA. <i>1, 31, a, 28 (444/440 av. J.C.)</i>, ἐμπίπτω ; ἐμφύω, ἐμ φιδακνίῳ, CIA. <i>2, 807, b, 114 (330 av. J.C.) ;</i> ἐμμένω ; ἔμψυχος ; ;<br><b>      2</b> ἐγ <i>devant</i> γ, κ, χ, ξ : ἐγγίγνομαι, ἐγκαλέω, ἐγχέω, ἐγξέω ; ;<br><b>      3</b> ἐλ <i>devant</i> λ : ἐλλείπω ; ἐλ λίμναις, CIA. <i>2, 817, a, 9 (358 av. J.C.) ;</i> ἐλ Λέσϐῳ, CIA. <i>2, 108, b, 13 (349 av. J.C.), etc. ; ;</i><br><b>      4</b> ἐρ <i>devant</i> ρ <i>dans qqes mots :</i> ἔρρινον ; ἐρ Ῥόδῳ, CIA. <i>1, 263, a, 15 et 262, 17 (av. 403 av. J.C.) ; (mais</i> ἔνρυθμος <i>à côté de</i> ἔρρυθμος ; ἐνράπτω <i>à côté de</i> ἐρράπτω) ; ;<br><b>      5</b> ἐς <i>devant</i> σ : ἐσ στήλῃ, CIA. <i>1, 103, 2 (403 av. J.C</i>.) ; ἐσ σίτου ἐνδείᾳ, CIA. <i>4, 22, c, 6 (av. 444 av. J.C</i>.) ; ἐς Σάμῳ, CIA. <i>1, 188, 35 (410 av. J.C.) ;</i> ἐς Σιδῶνι, CIA. <i>2, 86, 31 (376/365 av. J.C.) ; en ce cas qqf. réduit à</i> ἐ : ἐ στήλῃ, CIA. <i>4, 27, a, 59 (445 av. J.C.) ; 1, 45, 16 (421 av. J.C.), etc. ; ou renforcé en</i> εἰ : εἰ στήλῃ, CIA. <i>1, 52, a, 3 (420 av. J.C.) ; 2, 553, 8 (403 av. J.C.). — Sur ces exemples, v. Meisterh. p. 85 et 86</i>.<br><span><b><span class=\"arrow\"></span></b> ἐν <i>se fond en une crase avec l’art</i>. τά : τἀν, ESCHL. <i>Pr. 442, Ch. 579, et avec la conj</i>. καί : κἀν, ESCHL. <i>Ag. 1271, 1384 ; Suppl. 87, 834. — Formes poét. :</i> εἰν, HOM. <i>ll. cc. ; de même dans la loc</i>. εἰν Ἅιδου δόμοις, SOPH. <i>Ant. 1241 ;</i> — ἐνί, <i>anc. forme de locatif (v. ci-dessus)</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *h₁en(i), dedans ; <i>cf. anc. lat</i>. en <i>p</i>. in ; <i>sur l’identité d’origine de</i> ἐν <i>et de</i> εἰς, <i>v</i>. εἰς <i>fin</i>.<br><br>\n➁ <b>ἕν</b>, <i>neutre de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εν - ἐν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2769 fois dans 2115 versets de 27 livres bibliques (NT)\n<ul>\n<li>Matthieu (296)</li>\n<li>Marc (136)</li>\n<li>Luc (366)</li>\n<li>Jean (223)</li>\n<li>Actes (278)</li>\n<li>Romains (171)</li>\n<li>1 Corinthiens (173)</li>\n<li>2 Corinthiens (166)</li>\n<li>Galates (42)</li>\n<li>Ephésiens (125)</li>\n<li>Philippiens (66)</li>\n<li>Colossiens (88)</li>\n<li>1 Thessaloniciens (53)</li>\n<li>2 Thessaloniciens (27)</li>\n<li>1 Timothée (46)</li>\n<li>2 Timothée (37)</li>\n<li>Tite (13)</li>\n<li>Philémon (10)</li>\n<li>Hébreux (67)</li>\n<li>Jacques (38)</li>\n<li>1 Pierre (51)</li>\n<li>2 Pierre (41)</li>\n<li>1 Jean (77)</li>\n<li>2 Jean (8)</li>\n<li>3 Jean (3)</li>\n<li>Jude (9)</li>\n<li>Apocalypse (159)</li>\n</ul>\n</td></tr>\n</table>","G1723":"<h1>enagkalizomai</h1>\n<p>Strong n° 1723 <i>Prononciation [en-ang-kal-id'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prendre dans ses bras, embrasser</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·αγκαλίζομαι</b> <span>[κᾰ]</span> <span>(<i>impf</i>. ἐνηγκαλιζόμην, <i>ao</i>. ἐνηγκαλισάμην)</span><br><b>      1</b> <i>act</i>. prendre <i>ou</i> porter dans ses bras, ANTH. <i>7, 476 ;</i> PLUT. <i>Cam. 5, M. 335</i> d, <i>492</i> d ; SPT. <i>Prov. 6, 10 ; 24, 33 ;</i> SYMM. <i>Job 39, 13 ;</i><br><b>      2</b> <i>pass</i>. être porté dans les bras, DS. <i>3, 58 (part. prés</i>. ἐναγκαλιζομένων).<br><span><b>Étym</b>. ἐν, ἀγκάλη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εναγκαλιζομαι - ἐναγκαλίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G1724":"<h1>enalios</h1>\n<p>Strong n° 1724 <i>Prononciation [en-al'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui est dans la mer, maritime</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·άλιος, α</b> <i>ou</i> <b>ος, ον</b> <span>[ᾰλ]</span><br><b>      1</b> qui est <i>ou</i> vit dans la mer ; <i>en parl. de poissons,</i> OD. <i>4, 443 ; 5, 67 ;</i> SOPH. <i>Ant. 346 ; en parl. d’îles,</i> SOPH. <i>fr. 239 ;</i> ARSTT. <i>Mund. 3, 1 ; de villes ou de contrées situées au bord de la mer,</i> EUR. <i>I.A. 165, Ph. 6 ;</i><br><b>      2</b> qui vit sur mer, <i>en parl. de marins, de pêcheurs,</i> OD. <i>5, 67 ;</i> SOPH. <i>Aj. 565 ;</i><br><b>      3</b> qui concerne la mer <i>ou</i> les marins : ἐν. θεός, SOPH. <i>O.C. 888, 1497,</i> le dieu de la mer <i>ou</i> des marins (Poséidon).<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. ἐνάλιος, EUR. <i>Andr. 855, Hel. 526. Épq. et lyr</i>. εἰνάλιος, OD. <i>ll. cc. ;</i> PD. <i>P. 4, 39 ;</i> SOPH. <i>Ant. 346</i>.<br><span><b>Étym</b>. ἐν, ἅλς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εναλιος - ἐνάλιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1725":"<h1>enanti</h1>\n<p>Strong n° 1725 <i>Prononciation [en'-an-tee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>devant, en face de, en présence de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔναντι</b>, <i>adv. et prép. c</i>. ἔναντα SPT. <i>Ex. 28, 26 et 31 ; Sir. 38, 15 ; 51, 14 ;</i> NT. <i>Luc. 1, 8 ; Ap. 8, 21 ; avec un gén</i>. SPT. <i>Gen. 38, 7</i>.<br><span><b>Étym</b>. ἐν, ἀντί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εναντι - ἔναντι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1726":"<h1>enantion</h1>\n<p>Strong n° 1726 <i>Prononciation [en-an-tee'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sur, contre, opposé\n<ol type=\"a\">\n<li>endroits : opposés, contraires (comme le vent)</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>opposé comme un adversaire, hostile, en opposition en pensée ou en action</li>\n<li>un opposant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐναντίον</b>, <i>adv. v</i>. .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εναντιον - ἐναντίον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1727":"<h1>enantios</h1>\n<p>Strong n° 1727 <i>Prononciation [en-an-tee'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>contraire, opposé\n<ol type=\"a\">\n<li>de face (le vent)</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>opposé : adversaire, en opposition</li>\n<li>un opposant</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·αντίος, α, ον :<br>   I</b> <i>adj. :</i><br><b>      1</b> qui est en face de, vis-à-vis de, à l’encontre de, <i>dat. :</i> ἀκταὶ ἐναντίαι ἀλλήλῃσιν, OD. <i>10, 89,</i> rivages qui se font vis-à-vis ; ἐναντίον φαίνεσθαί τινι, OD. <i>6, 329,</i> se montrer en face de qqn ; τἀναντία τινί, XÉN. <i>Cyr. 3, 3, 45,</i> les choses qui s’offrent aux regards de qqn ; <i>avec mouv. :</i> οἱ ἐναντίη ἤλυθε μήτηρ, IL. <i>6, 251,</i> sa mère vint au-devant de lui ; δύο ἅμαξαι ἐν. ἀλλήλαις, THC. <i>1, 93,</i> deux chars qui viennent à la rencontre l’un de l’autre ; ἐξ ἐναντίας, HDT. <i>7, 225 (ion</i>. -ίης) ; THC. <i>4, 33, 35 ;</i> PLAT. <i>Tim. 68</i> a, <i>etc. ;</i> ἐκ τοῦ ἐναντίου, XÉN. <i>Hell. 4, 2, 22 ; 4, 5, 15 ;</i> ἐξ ἐναντίου, LUC. <i>Am. 44 ;</i> ἐκ τῶν ἐναντίων, POL. <i>5, 9, 9,</i> en face, à l’opposite ;<br><b>      2</b> <i>avec idée d’hostilité,</i> qui se tient en face de, <i>particul. dans un combat, avec le gén</i>. IL. <i>5, 497, etc. ;</i> SOPH. <i>Aj. 1284 ;</i> XÉN. <i>An. 4, 3, 28 ; avec le dat</i>. IL. <i>5, 12 ;</i> EUR. <i>Suppl. 856, I.T. 1415 ;</i> οἱ ἐν. l’ennemi, <i>litt</i>. ceux qui sont en face, THC. <i>4, 64 ; ou en gén</i>. la partie adverse, les adversaires <i>ou</i> l’adversaire, PLAT. <i>Rsp. 471</i> b ; <i>etc. ; en parl. de choses :</i> ἐν. στρατός, PD. <i>I. 6, 28,</i> armée ennemie ; ἐν. στρατόπεδον, PLAT. <i>Lach. 193</i> a, camp ennemi ;<br><b>      3</b> <i>p. ext</i>. opposé, contraire : τινί, SOPH. <i>Ph. 642,</i> à qqn ; <i>p. opp. à</i> φίλος, XÉN. <i>Hell. 6, 4, 5 ; à</i> σύμμαχος, XÉN. <i>An. 3, 2, 10 ;</i> τὸ ἐν. le parti opposé, XÉN. <i>Ath. 1, 4 ; adv</i>. τὸ ἐναντίον, <i>d’où</i> τοὐναντίον, XÉN. <i>Cyr. 8, 4, 9 ;</i> PLAT. <i>Phædr. 268</i> d, <i>Gorg. 468</i> b, <i>etc. ;</i> τὰ ἐναντία, <i>d’où</i> τἀναντία, THC. <i>6, 79 ;</i> SOPH. <i>Ant. 667, etc</i>. le contraire ; πᾶν τοὐναντίον, PLAT. <i>Leg. 967</i> a ; πάντα τἀναντία, XÉN. <i>Mem. 3, 12, 4,</i> tout le contraire ; <i>avec le gén</i>. τὰ ἐν. τούτων, HDT. <i>1, 82 ;</i> THC. <i>7, 75,</i> les choses contraires à celles-là ; <i>avec le dat</i>. τἀναντία τούτοις, PLAT. <i>Prot. 323</i> d, <i>m. sign. ;</i> τὴν ἐν. τινὶ ψῆφον θέσθαι, DÉM. <i>361, 26 ; ou simpl</i>. τὴν ἐναντίαν θέσθαι τινί, PLAT. <i>Lach. 184</i> d, déposer un suffrage contraire à celui de qqn ; <i>avec</i> ἤ : τοὐναντίον ἤ, PLAT. <i>Leg. 966</i> e ; AR. <i>Pl. 14 ;</i> τἀναντία ἤ, XÉN. <i>Mem. 3, 12, 4,</i> le contraire de ce que, contrairement à ce que ; ἐκ τῶν ἐναντίων, POL. <i>5, 9, 9 ;</i> κατὰ τἀναντία, PLAT. <i>Tim. 39</i> a, au contraire, par contre ;<br><b>   II</b> <i>adv. :</i><br><b>      1</b> ἐναντίον, en face, OD. <i>17, 544 ; 23, 107 ;</i> EUR. <i>Hec. 968, etc. ; avec le gén</i>. ἐν. τινός, EUR. <i>Hec. 975,</i> en face de ; <i>p. suite,</i> en présence de : ἐν. ἁπάντων λέγειν, THC. <i>6, 25,</i> dire en face de tous ; <i>cf</i>. SOPH. <i>O.C. 1002, etc. ;</i><br><b>      2</b> <i>avec idée d’hostilité (avec ou sans mouv.) avec le gén</i>. ἐν. μαχέσασθαί τινος, IL. <i>20, 97,</i> combattre en face de qqn ; ἐν. ἰέναι τινός, IL. <i>21, 574,</i> s’avancer en face de qqn ; <i>avec le dat</i>. ἐν. θεοῖς, EUR. <i>Or. 644,</i> malgré les dieux ; νεικεῖν ἀλλήλοισιν ἐν. IL. <i>20, 252,</i> se quereller les uns en face des autres ;<br><b>      3</b> ἐναντία, en face, HDT. <i>6, 32 ;</i> THC. <i>1, 29, etc</i>.<br><span>•<i> Cp</i>. ἐναντιώτερος, PLAT. <i>Rsp. 491</i> d ; ARSTT. <i>Nic. 2, 8</i>. <i>• Sup</i>. ἐναντιώτατος, THC. <i>3, 42 ;</i> XÉN. <i>Mem. 2, 3, 5 ;</i> PLAT. <i>Prot. 831</i> d ; PLUT. <i>M. 485</i> a, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. ἐναντίον <i>se construit avec le gén. au sens de</i> « en face de, devant », CIA. <i>1, 32, a, 20 (435/416 av. J.C.), etc. ; avec le dat. au sens de</i> « contre » CIA. <i>2, 609, 2 (324 av. J.C.) ; de même, en ce sens,</i> ἐναντία (<i>v. Meisterh. p. 176, 23</i>).<br><span><b>Étym</b>. ἐν, ἀντίος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εναντιος - ἐναντίος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Actes (3)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G1728":"<h1>enarchomai</h1>\n<p>Strong n° 1728 <i>Prononciation [en-ar'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>commencer, faire un commencement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἐν·άρχω</b> (<i>act. seul</i>. SPT. <i>Sir. 38, 16) d’ord. moy</i>. <b>ἐνάρχομαι</b> <span>(<i>f</i>. -άρξομαι, <i>pf</i>. -ῆργμαι)</span> commencer, <i>abs</i>. PLUT. <i>Cam. 32,</i> τινος, POL. <i>3, 54, 4 ; 5, 1, 3, etc. ;</i> PLUT. <i>Cic. 35 ;</i> περί τινος, LUC. <i>Philops. 39,</i> qqe ch. ; <i>avec l’inf</i>. POL. <i>5, 1, 5 ;</i> DH. <i>6, 13 ; avec l’acc. dans la locut</i>. ἐν. τὰ κανᾶ, EUR. <i>I.A. 1471,</i> commencer le sacrifice (<i>litt</i>. commencer à offrir les corbeilles sacrées) ; ἐνῆρκται τὰ κανᾶ, ESCHN. <i>70, 31,</i> on a offert les corbeilles, <i>càd</i>. le sacrifice est commencé.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εναρχομαι - ἐνάρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1729":"<h1>endees</h1>\n<p>Strong n° 1729 <i>Prononciation [en-deh-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>nécessiteux, indigent, dénué</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνδεής, ής, ές :<br>   I</b> qui manque de, <i>gén. :</i> σμικροῦ τινος ἐνδεής εἰμι, <i>avec un inf</i>. PLAT. <i>Prot. 329</i> b, il s’en faut de peu que je, <i>etc. ;</i><br><b>   II</b> <i>abs. :</i><br><b>      1</b> qui est dans le besoin, indigent, XÉN. <i>Hell. 6, 1, 3 ;</i><br><b>      2</b> incomplet, imparfait, insuffisant, THC. <i>8, 36 ;</i> SOPH. <i>Ph. 375 ;</i> EUR. <i>Hec. 835, Ph. 701 ;</i> πρός τι, PLAT. <i>Prot. 322</i> b, insuffisant pour qqe ch. ; τὸ ἐνδεές, THC. <i>1, 77,</i> insuffisance, défectuosité ; <i>plur</i>. τἀνδεᾶ, SOPH. <i>O.C. 1430,</i> ce qu’il y a de pire ;<br><b>   III</b> <i>au cp</i>. ἐνδεέστερος, inférieur à : τινος, THC. <i>1, 70,</i> SOPH. <i>Ph. 524,</i> à qqn <i>ou</i> à qqe ch. ; τινός τι, XÉN. <i>Hell. 7, 1, 23,</i> à qqn en qqe ch. ; τινος ὅτι, XÉN. <i>Cyr. 2, 2, 1,</i> à qqn en ce que ; τινι, THC. <i>2, 87 ;</i> ISOCR. <i>62</i> d, en qqe ch. ; <i>abs</i>. inférieur, insuffisant, qui laisse à désirer, HDT. <i>7, 48 ;</i> THC. <i>1, 10, etc</i>.<br><span><b>Étym</b>. ἐνδέω, manquer.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδεης - ἐνδεής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1730":"<h1>endeigma</h1>\n<p>Strong n° 1730 <i>Prononciation [en'-dighe-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>témoignage, évidence, preuve, indice</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνδειγμα, ατος (τὸ)</b> preuve, témoignage, PLAT. <i>Criti. 110</i> b ; DÉM. <i>423, 13</i>.<br><span><b>Étym</b>. ἐνδείκνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδειγμα - ἔνδειγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G1731":"<h1>endeiknumi</h1>\n<p>Strong n° 1731 <i>Prononciation [en-dike'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>désigner\n<ol type=\"a\">\n<li>montrer, démontrer, prouver, par des arguments ou des actes</li>\n</ol>\n</li>\n<li>manifester, étaler, afficher</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·δείκνυμι</b> <span>(<i>f</i>. -δείξω)</span><br><b>   I</b> <i>au propre,</i> montrer devant, montrer du doigt ; τι, PD. <i>O. 7, 58,</i> qqe ch. ; τινί τι, ESCHL. <i>Pr. 404,</i> qqe ch. à qqn ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> expliquer : τί τινι, ANT. <i>145, 40,</i> qqe ch. à qqn ; πρίν γ' ἂν ἐνδείξω τί δρῶ, SOPH. <i>O.C. 48,</i> avant d’avoir exposé la chose pour savoir ce que je dois faire ;<br><b>      2</b> ordonner : ἐνδ. τινί, <i>avec l’inf</i>. PLAT. <i>Rsp. 308</i> e, signifier <i>ou</i> ordonner à qqn de, <i>etc. ;</i><br><b>      3</b> indiquer, signaler, dénoncer, <i>d’où</i> poursuivre en justice, accuser, PLAT. <i>Ap. 32</i> b ; ἐνδ. ταῖς ἀρχαῖς, PLAT. <i>Leg. 856</i> c, dénoncer aux autorités, poursuivre devant les autorités ; <i>au pass</i>. κακοῦργος ἐνδεδειγμένος, ANT. <i>130, 16,</i> malfaiteur poursuivi en justice ; ἐνδειχθέντα <i>avec un inf</i>. DÉM. <i>573, 11,</i> accusé de, <i>etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> montrer devant soi : τινί τι, POL. <i>3, 54, 3,</i> qqe ch. à qqn ; τινα, POL. <i>18, 6, 2,</i> qqn ;<br><b>      2</b> faire connaître, montrer, prouver : τὸ εὔψυχον, THC. <i>4, 126 ;</i> τὴν εὔνοιαν, AR. <i>Pl. 585 ;</i> DÉM. <i>561, 25,</i> montrer sa générosité, ses bons sentiments ; ὡς <i>ou</i> ὅτι, <i>etc</i>. THC. <i>8, 82 ;</i> PLAT. <i>Ap. 23</i> b, montrer que, <i>etc. ; avec un part</i>. τὴν δύναμιν κρείττω οὖσαν, DÉM. <i>535 fin,</i> montrer que sa puissance est supérieure ; ἐνδείκνυσο σπουδάζων, ISOCR. <i>375</i> b, montre que tu as du zèle ;<br><b>      3</b> donner ses raisons, démontrer, expliquer : Πηλεΐδῃ, IL. <i>19, 83,</i> donner ses raisons au fils de Pélée ;<br><b>      4</b> se faire connaître, se faire valoir, PLAT. <i>Prot. 317</i> c ; τινι, DÉM. <i>375, 21 ;</i> ESCHN. <i>84 ;</i> ARSTT. <i>Œc. 2, 33 ;</i> PLUT. <i>Cic. 15,</i> auprès de qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδεικνυμι - ἐνδείκνυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 7 livres bibliques (NT)\n<ul>\n<li>Romains (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (2)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G1732":"<h1>endeixis</h1>\n<p>Strong n° 1732 <i>Prononciation [en'-dike-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>démonstration, preuve\n<ol type=\"a\">\n<li>manifestation faite par des actes</li>\n<li>signe, évidence</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνδειξις, εως (ἡ) :<br>      1</b> action de montrer, de faire voir, POL. <i>3, 38, 5 ; d’où</i> démonstration, PLAT. <i>Leg. 966</i> b ; <i>p. suite,</i> preuve, DC. <i>62, 23 ;</i> NT. <i>Rom. 3, 25 ;</i><br><b>      2</b> dénonciation, <i>d’où</i> poursuite <i>en particul. pour usurpation de fonctions publiques,</i> AND. <i>2, 26 ;</i> DÉM. <i>524, 24, etc. ;</i><br><b>      3</b> action de se faire valoir, de s’insinuer : πρός τινα, ESCHN. <i>85, 12,</i> auprès de qqn.<br><span><b>Étym</b>. ἐνδείκνυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδειξις - ἔνδειξις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1733":"<h1>hendeka</h1>\n<p>Strong n° 1733 <i>Prononciation [hen'-dek-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>onze\n<ol type=\"a\">\n<li>les onze disciples vivants après la mort de Judas</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἕν·δεκα</b> (οἱ, αἱ, τὰ) <i>n. de n. indécl</i>. onze, IL. <i>9, 329 ;</i> OD. <i>14, 103 ;</i> THCR. <i>Idyl. 11, 40 ;</i> CIA. <i>1, 273, h, 4, 7, 11, 13 (pas av. 420 av. J.C.), v. Meisterh. p. 126, 8</i>) ; οἱ ἕνδεκα, les Onze, <i>càd. les onze magistrats chargés de la police, de la surveillance des prisons et des exécutions capitales, à Athènes,</i> XÉN. <i>Hell. 1, 7, 10 ; 2, 3, 54, etc. ;</i> PLAT. <i>Ap. 37</i> c, <i>Phæd. 59</i> e, <i>etc. ;</i> AR. <i>Vesp. 1108 ;</i> ANT. <i>137, 35 ;</i> DÉM. <i>720, 24 ; 726, 8, etc. ; ou, dans le Nouveau-Testament,</i> les onze apôtres (moins Judas) NT. <i>Matth. 28, 16 ; Marc. 16, 14 ; Luc. 24, 9, 33, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδεκα - ἕνδεκα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nombre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1734":"<h1>hendekatos</h1>\n<p>Strong n° 1734 <i>Prononciation [hen-dek'-at-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>onzième</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑνδέκατος, η, ον</b> <span>[ᾰ]</span> onzième, IL. <i>21, 156 ;</i> OD. <i>19, 192 ; etc. ;</i> ἡ ἑνδεκάτη (<i>s.-e</i>. ἡμέρα) le onzième jour, IL. <i>24, 666 ;</i> OD. <i>2, 374, etc</i>.<br><span><b>Étym</b>. ἕνδεκα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδεκατος - ἑνδέκατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1735":"<h1>endechetai</h1>\n<p>Strong n° 1735 <i>Prononciation [en-dekh'-et-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>recevoir, admettre, approuver, permettre</li>\n<li>il peut être permis, il est possible, cela se peut</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·δέχομαι</b>, <i>ion</i>. <b>ἐνδέκομαι</b> <span>(<i>f</i>. -δέξομαι)</span><br><b>   I</b> <i>au sens act. :</i><br><b>      1</b> prendre sur soi, <i>acc</i>. HDT. <i>6, 11 ;</i> DÉM. <i>352, 26 ;</i><br><b>      2</b> accueillir, admettre, accepter, <i>acc</i>. HDT. <i>1, 60 ; 3, 80, etc. ;</i> THC. <i>3, 82 ; 8, 50 ;</i> AR. <i>Eq. 632, Th. 1129 ; avec une prop. inf</i>. admettre que, croire que, HDT. <i>3, 115 ; avec un suj. de chose :</i> μεταϐολὴν ἐνδ. PLAT. <i>Phæd. 78</i> d, admettre un changement, être exposé à changer ; καθ' ὅσον φύσις ἐνδέχεται, PLAT. <i>Tim. 69</i> a, autant que le permet la condition humaine ;<br><b>   II</b> <i>au sens pass</i>. être admissible, être permis, possible : ἃ ἐνδέχεται, THC. <i>4, 18,</i> ce qui est possible ; <i>partic</i>. ἐνδεχόμενος, η, ον, possible ; αἱ ἐνδ. τιμωρίαι, LYCURG. <i>164, 38,</i> les pénalités possibles ; τῆς ἐνδ. εὐδαιμονίας, ARSTT. <i>Pol. 7, 2, 17,</i> du bonheur possible ; <i>avec un inf</i>. τὰ ἐνδεχόμενα εἶναι καὶ μὴ εἶναι, ARSTT. <i>G.A. 2, 1, 2,</i> les choses qui peuvent être ou ne pas être, les choses contingentes ; <i>impers</i>. ἐνδέχεται, il est permis <i>ou</i> possible ; τινι, XÉN. <i>Hier. 4, 9 ;</i> DÉM. <i>859, 15,</i> à qqn ; <i>avec une prop. inf</i>. il est permis <i>ou</i> possible de <i>ou</i> que, THC. <i>1, 124, 140, etc. ;</i> καθ' ὅσον ἐνδέχεται, PLAT. <i>Phædr. 271</i> c ; <i>ou</i> εἰς ὅσον ἐνδέχεται, PLAT. <i>Rsp. 501</i> c ; μέχρις οὗ ἐνδέχεται, ARSTT. <i>Rhet. 1, 1, 14 ;</i> ὡς ἐνδέχεται μάλιστα, POL. <i>3, 49, 1,</i> autant qu’il est possible ; <i>et au partic</i>. εἰς τὸ ἐνδεχόμενον, HYPÉR. (STOB. <i>Fl. 124, 36</i>) ; εἰς τοὐνδεχόμενον, PLUT. <i>M. 2</i> c ; ἐκ τῶν ἐνδεχομένων, XÉN. <i>Mem. 3, 9, 4 ;</i> DS. <i>1, 54,</i> autant que faire se peut.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδεχεται - ἐνδέχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1736":"<h1>endemeo</h1>\n<p>Strong n° 1736 <i>Prononciation [en-day-meh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être parmi son peuple, demeurer dans son pays, rester à la maison</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·δημέω-ῶ :<br>      1</b> être établi <i>ou</i> séjourner dans un pays, LYS. <i>114, 36,</i> PLUT. <i>M. 578</i> e ; <i>fig</i>. se fixer (dans le corps) <i>avec</i> ἐν <i>et le dat</i>. NT. <i>2Cor. 5, 6 ;</i><br><b>      2</b> venir se fixer, <i>avec</i> εἰς <i>et l’acc</i>. CHARIT. <i>6, 3</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδημεω - ἐνδημέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G1737":"<h1>endidusko</h1>\n<p>Strong n° 1737 <i>Prononciation [en-did-oos'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>se vêtir, habiller, être vêtu, être habillé de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·διδύσκω</b> (<i>seul. prés</i>.) <span>[ῐ]</span> revêtir : τινά τι, SPT. <i>2Reg. 1, 24,</i> NT. <i>Marc. 15, 17,</i> qqn de qqe ch. ;<br><b><i>Moy.</i></b> (<i>seul. prés. et impf</i>. ἐνεδιδυσκόμην) se revêtir de, <i>acc</i>. NT. <i>Luc. 8, 27, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδιδυσκω - ἐνδιδύσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G1738":"<h1>endikos</h1>\n<p>Strong n° 1738 <i>Prononciation [en'-dee-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>selon le droit, juste, conforme à la justice</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔν·δικος, ος, ον</b> <span>[ῐ]</span> conforme à la justice :<br><b>      1</b> <i>en parl. de choses,</i> juste, légitime, PD. <i>P. 5, 138 ;</i> ESCHL. <i>Ch. 330 ;</i> ὑμῖν ἔνδικα, SOPH. <i>Aj. 1282,</i> choses par vous reconnues justes, <i>càd</i>. approuvées par vous ; ἔνδικα πράττειν, EUR. <i>Or. 538,</i> avoir le sort qu’on mérite ; πόλις ἔ. PLAT. <i>Hipp. ma. 292</i> b, État gouverné avec justice ;<br><b>      2</b> <i>en parl. de pers</i>. juste, équitable, ESCHL. <i>Eum. 699 ;</i> SOPH. <i>Ant. 208 ;</i> PLAT. <i>Leg. 915</i> d.<br><span>•<i> Cp</i>. -ώτερος, ESCHL. <i>Sept. 673, Suppl. 590</i>. <i>• Sup</i>. -ώτατος, ESCHL. <i>fr. 198 ;</i> SOPH. <i>O.C. 925</i>.<br><span><b>Étym</b>. ἐν, δίκη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδικος - ἔνδικος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1739":"<h1>endomesis</h1>\n<p>Strong n° 1739 <i>Prononciation [en-dom'-ay-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui est construit\n<ol type=\"a\">\n<li>le matériau mis dans un mur, donc dans lequel le mur est composé</li>\n<li>une jetée construite dans la mer pour briser les vagues, et ainsi construire un port</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνδόμησις, εως (ἡ) :<br>      1</b> pilier, assise d’un bâtiment, NT. <i>Apoc. 21, 18 ;</i><br><b>      2</b> môle, digue, JOS. <i>A.J. 15, 9, 6</i>.<br><span><b>Étym</b>. ἐνδομέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδομησις - ἐνδώμησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1740":"<h1>endoxazo</h1>\n<p>Strong n° 1740 <i>Prononciation [en-dox-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>glorifié, orné de gloire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἐν·δοξάζω</b>, glorifier, SPT. <i>Ex. 33, 16 ; Ps. 88, 6 ; Sir. 38, 6, etc. ; au pass</i>. SPT. <i>Ex. 14, 4 ;</i> NT. <i>2Thess. 1, 10 et 12</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδοξαζω - ἐνδοξάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G1741":"<h1>endoxos</h1>\n<p>Strong n° 1741 <i>Prononciation [en'-dox-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tenu en bonne ou grande estime, de haut renom\n<ol type=\"a\">\n<li>illustre, honorable, estimé</li>\n<li>notable, glorieux</li>\n<li>splendide, resplendissant\n<ol>\n<li>de vêtements</li>\n<li>fig., affranchi du péché</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔν·δοξος, ος, ον :<br>      1</b> conforme à l’opinion commune, ARSTT. <i>Top. 1, 1, 3 ;</i><br><b>      2</b> <i>plus souv</i>. renommé, célèbre, illustre, <i>en parl. de pers</i>. THGN. <i>195 ;</i> XÉN. <i>Mem. 1, 2, 56 ;</i> PLAT. <i>Soph. 223</i> b, <i>etc. ;</i> εἴς τι, XÉN. <i>Mem. 3, 5, 1 ;</i> ἐπί τινι, LUC. <i>Harm. 1, Pseud. 26,</i> pour qqe ch. ; <i>en parl. de choses :</i> ἔνδ. πράγματα, ESCHN. <i>86, 42,</i> actions illustres ; ἔνδ. ταφαί, PLUT. <i>Per. 28,</i> sépultures glorieuses ; τὰ ἔνδοξα, POL. <i>1, 2, 5 ; 12, 5, 6,</i> la gloire.<br><span>•<i> Cp</i>. ἐνδοξότερος, XÉN. <i>Ages. 1, 19 ;</i> ISOCR. <i>10</i> b ; DC. <i>38, 26, etc.</i> <i>• Sup</i>. -ότατος, XÉN. <i>Œc. 6, 10 ;</i> DC. <i>59, 14</i>.<br><span><b>Étym</b>. ἐν, δόξα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδοξος - ἔνδοξος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1742":"<h1>enduma</h1>\n<p>Strong n° 1742 <i>Prononciation [en'-doo-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vêtement, parure, manteau, vêtement extérieur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνδυμα, ατος (τὸ)</b> <span>[ῡ]</span> vêtement, STR. <i>3, 3, 7 Kram. ;</i> PLUT. <i>Sol. 8 ;</i> SPT. <i>2Reg. 1, 24 ; Prov. 29, 40, etc. ;</i> NT. <i>Matth. 7, 15, etc. ;</i> JOS. <i>A.J. 3, 7, 2 ; B.J. 5, 5, 7</i>.<br><span><b>Étym</b>. ἐνδύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδυμα - ἔνδυμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1743":"<h1>endunamoo</h1>\n<p>Strong n° 1743 <i>Prononciation [en-doo-nam-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être fort, doté de force, fortifié, rendre robuste</li>\n<li>recevoir de la force, augmenter en force</li>\n<li>dans un mauvais sens\n<ol type=\"a\">\n<li>être hardi, forte tête</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνδυναμόω-ῶ</b> <span>(<i>ao. pass</i>. ἐνεδυναμώθην)</span> <span>[ῠᾰ]</span> rendre fort <i>ou</i> puissant, NT. <i>1Tim. 1, 12 ; au pass</i>. NT. <i>Rom. 4, 20 ; fig</i>. se fortifier (dans sa vanité) SPT. <i>Ps. 51, 9</i>.<br><span><b>Étym</b>. ἐνδύναμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδυναμοω - ἐνδυναμόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 7 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1744":"<h1>enduno</h1>\n<p>Strong n° 1744 <i>Prononciation [en-doo'-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>envelopper, cacher\n<ol type=\"a\">\n<li>littéralement : enfiler un vêtement</li>\n<li>métaph. revêtir une armure</li>\n</ol>\n</li>\n<li>se glisser dans, s'insinuer dans, entrer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·δύνω</b> (<i>seul. prés. et impf</i>.) revêtir, se revêtir de : χιτῶνα, IL. <i>2, 42,</i> d’une tunique ; περὶ στήθεσσι χιτῶνα, IL. <i>10, 21, 131,</i> d’une tunique autour de sa poitrine.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. poét. 3 sg</i>. ἔνδυνε, IL. <i>2, 42 ; 10, 21</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδυνω - ἐνδύνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1745":"<h1>endusis</h1>\n<p>Strong n° 1745 <i>Prononciation [en'-doo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un revêtement, action de se vêtir, d'ou port d'un vêtement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνδυσις, εως (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> action d’entrer, de pénétrer, PLAT. <i>Crat. 419</i> c ;<br><b>      2</b> action de se vêtir, de se couvrir, ATH. <i>550</i> d ; SPT. <i>Job 41, 5, etc</i>.<br><span><b>Étym</b>. ἐνδύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδυσις - ἔνδυσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1746":"<h1>enduo</h1>\n<p>Strong n° 1746 <i>Prononciation [en-doo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'enfoncer dans (des vêtements), vêtir, se vêtir, se revêtir</li>\n<li>s'habiller</li>\n<li>s'introduire dans</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·δύω :<br>   I</b> <i>tr. (prés., impf., f</i>. -δύσω <i>et ao.1</i> ἐνέδυσα) faire entrer dans, <i>d’où</i> vêtir, habiller : ἄγαλμα, HDT. <i>2, 42,</i> une statue ; τινά τι, XÉN. <i>Cyr. 1, 3, 3 ;</i> AR. <i>Lys. 1021,</i> qqn de qqe ch. ; τινὰ ὅπλοις, BATR. <i>160,</i> revêtir qqn d’une armure ;<br><b>   II</b> <i>intr. (ao.2</i> ἐνέδυν, <i>pf</i>. ἐνδέδυκα <i>et au moy</i>.) :<br><b>      1</b> entrer dans, pénétrer dans : τοῖς ταύροις, PLUT. <i>M. 55</i> e, s’enfoncer dans le flanc des taureaux, <i>en parl. de l’aiguillon ; d’où abs</i>. entrer, HDT. <i>2, 121, 2 ;</i> PLUT. <i>M. 38</i> a, <i>etc. ; avec l’acc</i>. (ψυχὴ) πίθηκον ἐνδυομένη, PLAT. <i>Rsp. 620</i> c, (âme) qui entre dans le corps d’un singe ; <i>fig</i>. εἴς τινα, THC. <i>3, 6 ;</i> AR. <i>Vesp. 1020 ; etc. ;</i> τινί, XÉN. <i>Cyr. 2, 1, 13 ;</i> PLAT. <i>Leg. 642</i> b, entrer dans l’âme de qqn, <i>en parl. d’un sentiment, d’un désir, etc. ; avec un suj. de pers. :</i> ἐ. τόλμημα, AR. <i>Eccl. 288,</i> prendre sur soi hardiment de faire qqe ch. ; ἐ. εἰς τὴν ἐπιμέλειαν, XÉN. <i>Cyr. 8, 1, 12,</i> se charger du soin de qqe ch. (<i>litt</i>. entrer dans, <i>etc</i>.) ;<br><b>      2</b> <i>particul</i>. se vêtir, se revêtir de (<i>d’un vêtement, d’une armure, etc.) acc</i>. HDT. <i>7, 218 ;</i> EUR. <i>Bacch. 853, etc. ; fig</i>. revêtir (les traits de qqn, un sentiment, <i>etc</i>.) DH. <i>11, 5 ;</i> NT. <i>Eph. 4, 24</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. moy. 3 sg. opt</i>. ἐνδύσαιτο, ANTH. <i>7, 268</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενδυοω - ἐνδύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 26 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (5)</li>\n<li>Luc (3)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (3)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G1747":"<h1>enedra</h1>\n<p>Strong n° 1747 <i>Prononciation [en-ed'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une embuscade</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνέδρα, ας (ἡ) :<br>   I</b> action d’asseoir, de poser ; <i>particul</i>. apposition (d’un bandage, <i>etc</i>.) HPC. <i>764, 768 ;</i><br><b>   II</b> action de poster dans, <i>d’où</i> embuscade, THC. <i>5, 56, etc. ;</i> ἐνέδραν ποιεῖσθαι, THC. <i>3, 90 ;</i> κατασκευάζειν, XÉN. <i>Hipp. 4, 10 ;</i> τιθέναι, DS. <i>19, 108 ;</i> θέσθαι, PLUT. <i>Rom. 23,</i> disposer <i>ou</i> dresser une embuscade, <i>p. suite :</i><br><b>      1</b> lieu où l’on dresse une embuscade, THC. <i>4, 67 ;</i><br><b>      2</b> troupe en embuscade, XÉN. <i>Hell. 4, 8, 37 ;</i><br><b>      3</b> <i>fig</i>. embûche, ruse, PLAT. <i>Leg. 908</i> d ; APP. <i>Civ. 1, 30</i>.<br><span><b>Étym</b>. ἐν, ἕδρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεδρα - ἐνέδρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1748":"<h1>enedreuo</h1>\n<p>Strong n° 1748 <i>Prononciation [en-ed-ryoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tendre un piège, préparer une embuscade</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνεδρεύω</b> <span>(<i>impf</i>. ἐνήδρευον, <i>f</i>. ἐνεδρεύσω, <i>ao</i>. ἐνήδρευσα, <i>pf. inus. ; pass. ao</i>. ἐνηδρεύθην, <i>pf</i>. ἐνήδρευμαι)</span><br><b>      1</b> être <i>ou</i> se mettre en embuscade dans, <i>avec</i> ἐς <i>et l’acc</i>. THC. <i>4, 67 ;</i> ἐν. τινά, PLUT. <i>Popl. 22,</i> tendre une embuscade à qqn ; <i>fig</i>. tendre un piège : τινά, DÉM. <i>1011, 3,</i> à qqn ; <i>au pass</i>. être guetté <i>ou</i> pris au piège, XÉN. <i>Mem. 2, 1, 4 ; fig</i>. DÉM. <i>836, 13 ;</i><br><b>      2</b> mettre en embuscade, APP. <i>Civ. 2, 76 ;</i> JOS. <i>A.J. 5, 8, 11 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἐνεδρευσάμην)</span> tendre une embuscade, un piège, XÉN. <i>Hell. 4, 4, 15</i>.<br><span><b>Étym</b>. ἐνέδρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεδρευω - ἐνεδρεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1749":"<h1>enedron</h1>\n<p>Strong n° 1749 <i>Prononciation [en'-ed-ron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un guet-apens, une embuscade</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνεδρον, ου (τὸ)</b> embuscade, SPT. <i>Num. 35, 20 ; Jos. 8, 2, 12 ; 1 Macc. 1, 36 ; 10, 80 ; etc. ;</i> NT. <i>Ap. 23, 16</i>.<br><span><b>Étym</b>. ἐνέδρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεδρον - ἔνεδρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1750":"<h1>eneileo</h1>\n<p>Strong n° 1750 <i>Prononciation [en-i-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>enrouler, rouler dans, envelopper, terminer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·ειλέω-ῶ</b>, rouler dans, envelopper dans, <i>dat</i>. PLUT. <i>Artax. 11, etc. ;</i> ἐν <i>avec le dat</i>. ARTÉM. <i>1, 13 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. Q. SM. <i>14, 294</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενειλεω - ἐνειλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G1751":"<h1>eneimi</h1>\n<p>Strong n° 1751 <i>Prononciation [en'-i-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>être dans, ce qui est dedans, c.à.d l'âme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔν·ειμι</b> <span>(<i>impf</i>. ἐνῆν, <i>f</i>. ἐνέσομαι)</span><br><b>      1</b> être dans, <i>dat. ; en parl. d’objets matériels :</i> ἄργυρος ἀσκῷ ἔνεστι, OD. <i>10, 45,</i> il y a de l’argent dans une outre ; <i>p. anal</i>. εἰ χάλκεόν μοι ἦτορ ἐνείη, IL. <i>2, 490,</i> si j’avais un cœur d’airain ; νοῦς ὑμῖν ἔνεστι, SOPH. <i>El. 1328,</i> vous avez de l’intelligence ; πόλλ' ἔνεστι τῷ γήρᾳ κακά, AR. <i>Vesp. 441,</i> la vieillesse a bien des inconvénients ; <i>cf</i>. IL. <i>18, 53 ;</i> OD. <i>21, 288 ; avec</i> ἐν <i>et le dat</i>. HDT. <i>7, 112 ;</i> ESCHL. <i>Pr. 832, etc. ;</i><br><b>      2</b> être parmi, <i>avec un dat. pl</i>. THGN. <i>1135 ;</i> HDT. <i>3, 81, etc. ;</i><br><b>      3</b> être dans l’intervalle : ἐνέσται χρόνος, THC. <i>1, 80,</i> il se passera du temps d’ici là ;<br><b>      4</b> être possible à, au pouvoir de, <i>dat</i>. SOPH. <i>El. 527 ;</i> EUR. <i>I.T. 998 ;</i> DÉM. <i>527, 12, etc. ; abs</i>. SOPH. <i>O.R. 578 ; impers</i>. ἔνεστι (<i>ou</i> ἔνι, PLAT. <i>Phæd. 77</i> e, <i>Parm. 158</i> c ; CIA. <i>2, 652, b, 32, de 398 av. J.C. ;</i> CIA. <i>835, de 320/318 av. J.C., avec 19 exemples ; v. Meisterh. p. 153, 12 ; etc</i>.) il est possible, <i>avec l’inf</i>. DÉM. <i>1306, 3, etc. ; abs</i>. DÉM. <i>19, 6 ; avec un superl</i>. ὡς ἔνι ἥδιστα, XÉN. <i>Mem. 4, 5, 9,</i> le plus agréablement possible ; ὡς ἔνι μάλιστα, LUC. <i>Prom. 6,</i> le plus possible ; <i>cf</i>. POL. <i>16, 20, 7 ; 21, 2, 14 ; 23, 14, 2, etc. ; au participe neutre abs</i>. ἐνόν, étant possible, lorsqu’on peut : ἐνὸν αὐτοῖς σῴζεσθαι, HDN <i>8, 3,</i> puisqu’il leur était possible d’être sauvés ; ὡς οὐκ ἐνόν, LUC. <i>Anach. 9,</i> comme il n’est pas possible ; τὰ ἐνόντα, PLAT. <i>Rsp. 488</i> c, les ressources, les biens ; ἐκ τῶν ἐνόντων, DÉM. <i>312, 20,</i> selon les moyens, autant que possible.<br><span><b>Étym</b>. ἐν, εἰμί.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενειμι - ἔνειμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1752":"<h1>heneka</h1>\n<p>Strong n° 1752 <i>Prononciation [hen'-ek-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>à cause de, en vue de, pour l'amour de</li>\n<li>pour cette cause, donc</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἕνεκα, A</b> <i>prép. avec le gén. d’ord. après son rég. (v. ci-dessous</i>) :<br><b>   I</b> à cause de, <i>càd. :</i><br><b>      1</b> à cause de, en raison de, pour (<i>au sens du lat</i>. propter) ; <i>d’ord. après son rég. :</i> ἧς εἵνεκ', IL. <i>14, 89</i> (la ville de Troie) à cause de laquelle ; ὕϐριος εἵνεκα τῆσδε, IL. <i>1, 214,</i> à cause de cet outrage ; τοῦδ' ἕνεκα, IL. <i>1, 110,</i> à cause de cela ; ὧν ἕν. IL. <i>20, 21,</i> à cause de quoi, c’est pourquoi, <i>formule us. dans les inscr. att. j. à la fin du 4<sup>e</sup> siècle av. J.C., remplacée alors par</i> διόπερ, <i>et, au 1<sup>er</sup> siècle av. J.C., par</i> ὅθεν (<i>v. Meisterh. p. 211, 26</i>) ; τίνος ἕν. ; ESCHL. <i>fr. 180,</i> à cause de quoi ? <i>dans les inscr. att. touj. après son rég</i>. CIA. <i>2, add. 1, b, 34 (403 av. J.C.), etc. (v. Meisterh. p. 178, 27, note 1479) ; séparée de son rég. par plus. mots,</i> HDT. <i>1, 90 ;</i> AR. <i>Eccl. 106 ; qqf. avant son rég</i>. κολακεύειν ἕνεκα μισθοῦ, XÉN. <i>Hell. 5, 1, 17,</i> flatter pour recevoir un salaire ; <i>cf</i>. IL. <i>1, 94 ; 2, 377, etc. ;</i> PLAT. <i>Lys. 218</i> d ; <i>rar. au commenc. de la prop</i>. ARSTT. <i>G.A. 2, 5 ;</i><br><b>      2</b> à cause de, en faveur de, pour l’amour de (<i>au sens du lat</i>. causa <i>ou</i> gratia) THCR. <i>Idyl. 28, 13 ; 29, 37 ; en ce sens pléon. avec d’autres prép. :</i> τίνος δὴ χάριν ἕνεκα ; PLAT. <i>Leg. 701</i> d, <i>etc</i>. pour l’amour de qui… ? ;<br><b>      3</b> par le fait de : σέθεν δ' ἕνεκεν Ἀχέροντα οὐκ ἐπέρασεν, THCR. <i>Idyl. 17, 46,</i> c’est grâce à toi (<i>litt</i>. à cause de toi, par ton fait) que (Bérénice) n’a point passé l’Achéron ;<br><b>   II</b> par rapport à, quant à, HDT. <i>1, 42 ; en ce sens souv. accompagné de</i> γε : ἐμοῦ γ' ἕνεκα, AR. <i>Ach. 389 ;</i> DÉM. <i>461, 12,</i> du moins en ce qui me concerne ; ἕνεκά γε τῶν ἡμετέρων ὀφθαλμῶν, XÉN. <i>Mem. 4, 3, 3,</i> du moins en ce qui regarde nos yeux ;<br><b>B</b> <i>conj. c</i>. οὕνεκα, parce que, HH. <i>Ven. 199 ;</i> PD. <i>I. 7, 69 ;</i> A. RH. <i>4, 1523</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. ἔνεκα, THCR. <i>Idyl. 28, 13, avec</i> ἔν- <i>long</i> (ἔννεκ' <i>Ahrens). — Des deux formes en</i> -α (ἕνεκα, εἵνεκα), <i>la 1<sup>re</sup> seule d’ord. us. en prose att. ;</i> εἵνεκα, <i>poét</i>. (IL. <i>1, 174 ;</i> OD. <i>2, 191, etc. ;</i> CIA. <i>4, 477, e, 2, vers 450 av. J.C. ; etc.) et ion</i>. (HDT. <i>8, 35) ne se rencontre dans les inscr. att. en prose qu’au temps de l’empire romain, et, alors, qqf. écrit</i> ἵνεκα, CIA. <i>3, 785, 3 (de 30 av. J.C. à 68 après J.C.). Des deux formes en</i> -εν (ἕνεκεν, εἵνεκεν, <i>rar</i>. ἕνεκε, εἵνεκε), <i>la 1<sup>re</sup>, d’abord peu usitée en prose att</i>. (THC. <i>1, 68 ; 6, 2 ;</i> XÉN. <i>Hell. 2, 1, 14, etc. ;</i> PLAT. <i>Phædr. 259</i> d, <i>etc.) finit par devenir dominante ; la 2<sup>e</sup> ion</i>. (HDT. <i>1, 42, etc.) et de poésie att</i>. (POSIDIPP. <i>dans</i> ATH. <i>412</i> e, <i>etc.) ne se rencontre dans les inscr. att. en prose que sous l’empire,</i> CIA. <i>3, 697, 9 (après 161 apr. J.C.). Quant aux 2 formes de prose att</i>. (ἕνεκα, ἕνεκεν) <i>elles se rencontrent dans la proportion de 30</i> ἕνεκα <i>contre 2</i> ἕνεκεν <i>j. à la fin du 4<sup>e</sup> siècle ; vers 282 av. J.C. on trouve</i> ἕνεκεν <i>dans un décret,</i> CIA. <i>2, 316, 21, 30 (282/280 av. J.C.) et au 2<sup>e</sup> s</i>. ἕνεκεν <i>est devenu dominant dans la proportion de 12</i> ἕνεκεν <i>contre 4</i> ἕνεκα. (<i>Sur l’emploi de ces diverses formes, v. Meisterh. p. 176 et suiv</i>.).<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεκα - ἕνεκα</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 22 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (4)</li>\n<li>Luc (4)</li>\n<li>Actes (3)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (4)</li>\n</ul>\n</td></tr>\n</table>","G1753":"<h1>energeia</h1>\n<p>Strong n° 1753 <i>Prononciation [en-erg'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>action, fonctionnement, compétence, efficacité, efficience, énergie, force à l'œuvre dans\n<ol type=\"a\">\n<li>dans le N.T est utilisé seulement pour un pouvoir surhumain, que ce soit de Dieu ou du Diable</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνέργεια, ας (ἡ) :<br>   I</b> force en action (<i>p. opp. à</i> δύναμις, force en puissance), <i>d’où</i> activité, ARSTT. <i>Metaph. 8, 6, 1, etc. ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> action <i>ou</i> fonctionnement (d’un mécanisme) HÉRON <i>Aut. 244 ;</i><br><b>      2</b> action, acte (<i>p. opp. à</i> ἕξις, manière d’être, état) ARSTT. <i>Nic. 1, 7 ; d’où</i> force des choses, DS. <i>20, 95 ;</i> force <i>ou</i> vivacité dans le discours, ARSTT. <i>Rhet. 3, 11, 12 ;</i><br><b>      3</b> action, influence, <i>en mauv. part, en parl. du mauv. esprit,</i> CLÉM. <i>2, 629</i>.<br><span><b>Étym</b>. ἐνεργής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεργεια - ἐνέργεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – force, puissance, pouvoir souvent oppressif s'exerçant par des actes de violence\n<br><br> – puissance, capacité naturelle, générale et inhérente\n<br><br> – action, efficacité, pouvoir dans l'exercice, pouvoir opérant  – d'abord liberté d'action ; donc autorité – soit un pouvoir qui a été délégué, ou un pouvoir sans restriction, arbitraire\n<br><br> – force, vertu, puissance (spécialement physique), comme reçue en don\n<br><br> – puissance, force souveraine, le pouvoir manifesté ; – dans le NT il s'agit surtout de la force et du pouvoir de Dieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Ephésiens (3)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n</ul>\n</td></tr>\n</table>","G1754":"<h1>energeo</h1>\n<p>Strong n° 1754 <i>Prononciation [en-erg-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être opérant, être à l'œuvre, agir puissamment, produire, opérer\n<ol type=\"a\">\n<li>travailler pour quelqu'un, aider quelqu'un</li>\n</ol>\n</li>\n<li>effectuer</li>\n<li>afficher son activité, montrer son efficacité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνεργέω-ῶ</b> <span>(<i>impf</i>. ἐνήργουν, <i>etc</i>.)</span><br><b>      1</b> agir, produire, <i>surt. en parl. de l’activité de l’esprit,</i> ARSTT. <i>Nic. 1, 1, 15 ;</i><br><b>      2</b> accomplir, exécuter <i>en gén. :</i> τι, POL. <i>17, 14, 8,</i> qqe ch. ; <i>particul</i>. diriger activement (une guerre) POL. <i>1, 13, 5 ;</i><br><b>      3</b> agir sur, influencer ; <i>en mauv. part, particul. en parl. du mauvais esprit,</i> CLÉM. <i>1, 60 ;</i> NAZ. <i>953 edd. Migne, etc. ;</i><br><b>      4</b> <i>c</i>. βινεῖν, THCR. <i>Idyl. 4, 61 ; avec un acc. de pers</i>. ALCIPHR. <i>3, 55 ;</i><br><b><i>Moy.</i></b> opérer, agir, NT. <i>Rom. 7, 5, etc</i>.<br><span><b>Étym</b>. ἐνεργής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεργεω - ἐνεργέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 19 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1755":"<h1>energema</h1>\n<p>Strong n° 1755 <i>Prononciation [en-erg'-ay-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>chose travaillée, façonnée, réalisation, effet</li>\n<li>opération effectuée, acte, effet</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνέργημα, ατος (τὸ)</b> acte, effet, opération, POL. <i>2, 42, 7 ; 4, 8, 7 ;</i> DS. <i>4, 51, etc. ; p. opp. à</i> πάθος, SEXT. <i>67, 14 Bkk</i>.<br><span><b>Étym</b>. ἐνεργέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεργημα - ἐνέργημα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\t\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G1756":"<h1>energes</h1>\n<p>Strong n° 1756 <i>Prononciation [en-er-gace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>actif, efficace, effectif, agissant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·εργής, ής, ές</b>, agissant, actif, efficace, POL. <i>2, 65, 12 ; 11, 23, 2 ;</i> DS. <i>1, 88 ; 17, 44 ;</i> NT. <i>1Cor. 6, 9 ;</i> πρός τι, ARSTT. <i>Top. 1, 12,</i> pour qqe ch. ; <i>en parl. du sol,</i> productif, PLUT. <i>Sol. 31</i>.<br><span>•<i> Cp</i>. -έστερος, ARSTT. <i>Top. 1, 12 ;</i> PLUT. <i>Sol. 31 ;</i> DIOSC. <i>1, 11 et 82</i>. <i>• Sup</i>. -έστατος, DS. <i>1, 88 ;</i> DIOSC. <i>1, 18</i>.<br><span><b>Étym</b>. ἐν, ἔργον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεργης - ἐνεργής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1757":"<h1>eneulogeo</h1>\n<p>Strong n° 1757 <i>Prononciation [en-yoo-log-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>conférer des bienfaits, bénir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·ευλογέω-ῶ</b>, bénir dans, <i>dat</i>. SPT. <i>Gen. 12, 3 ; Ps. 71, 17 ;</i> NT. <i>Ap. 3, 25,</i> GAL. <i>3, 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενευλογεω - ἐνευλογέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G1758":"<h1>enecho</h1>\n<p>Strong n° 1758 <i>Prononciation [en-ekh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tenir dans\n<ol type=\"a\">\n<li>être tenu, empêtré, pris au piège</li>\n<li>être engagé, se tenir contre, garder de la rancune contre quelqu'un, avoir de la colère contre, en vouloir à quelqu'un, être hostile</li>\n<li>Passif être retenu dans, être mis dessous, se mettre sous</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·έχω</b> <span>(<i>f</i>. ἐνέξω, <i>ao.2</i> ἐνέσχον ; <i>pass. f. de forme moy</i>. ἐνέξομαι, <i>ao.1</i> ἐνεσχέθην, <i>ao.2</i> ἐνεσχόμην)</span><br><b>   I <i>tr</i>.<br>      1</b> garder dans : χόλον τινί, HDT. <i>1, 118, etc</i>. conserver dans son cœur du ressentiment contre qqn ;<br><b>      2</b> retenir dans, <i>d’où au pass</i>. ἐνέχεσθαι, être retenu dans (un lien, une entrave, <i>etc.) dat</i>. HDT. <i>2, 121 ;</i> XÉN. <i>An. 7, 4, 17 ;</i> AR. <i>Eccl. 357 ; fig</i>. ἐν θωΰματι, HDT. <i>7, 128,</i> être saisi d’admiration ; ἐν κακῷ, HDT. <i>9, 37,</i> être plongé dans le malheur ; <i>ou simpl. avec le dat</i>. ὅρκοις, PAUS. <i>3, 24, 7,</i> être lié par des serments ; <i>p. suite,</i> être exposé <i>ou</i> soumis à : ζημίᾳ, PLAT. <i>Leg. 935</i> c ; αἰτίᾳ, PLAT. <i>Crit. 52</i> a, être atteint par une peine, une accusation ;<br><b>      3</b> (<i>au pass</i>.) se maintenir dans, <i>avec</i> ἐν <i>et le dat</i>. PLAT. <i>Theæt. 147</i> d ;<br><b>      4</b> (<i>au pass</i>.) être rencontré par : ἀγγελίᾳ, PD. <i>P. 8, 70,</i> par une nouvelle, recevoir une nouvelle ;<br><b>   II <i>intr</i>.<br>      1</b> s’enfoncer dans, se fixer dans : εἴς τι, XÉN. <i>Cyn. 10, 7 ;</i> κατά τι, PLUT. <i>Pomp. 71,</i> dans qqe ch. ;<br><b>      2</b> <i>fig</i>. s’attacher : τινί, SPT. <i>Gen. 49, 23 ;</i> NT. <i>Marc. 6, 19 ; Luc. 11, 53,</i> à qqn pour lui nuire, s’acharner après qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενεχω - ἐνέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Galates (2)</li>\n</ul>\n</td></tr>\n</table>","G1759":"<h1>enthade</h1>\n<p>Strong n° 1759 <i>Prononciation [en-thad'-eh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ici, avec ou sans mouvement</li>\n<li>là</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνθάδε</b>, <i>adv</i>., ici :<br><b>      1</b> <i>en parl. du lieu,</i> ici même, OD. <i>15, 492 ;</i> SOPH. <i>Ph. 304, 377 ;</i> THC. <i>6, 36 ; joint à</i> αὐτοῦ : ἐνθάδ' αὐτοῦ, ici même, SOPH. <i>O.C. 78 ;</i> EUR. <i>Tr. 716 ;</i> AR. <i>Pl. 1188, Vesp. 765 ;</i> οἱ ἐνθάδε, ceux d’ici, <i>càd</i>. les vivants ; <i>p. opp. à</i> οἱ κάτω, PD. <i>O. 2, 104 ;</i> ESCHL. <i>Suppl. 923 ;</i> SOPH. <i>Ant. 75 ;</i> PLAT. <i>Gorg. 525</i> b ; <i>ou</i> les gens de ce pays, SOPH. <i>O.C. 42 ;</i> τὰ ἐνθάδε, THC. <i>6, 17,</i> les affaires de ce pays, <i>p. opp. à</i> τἀκεῖ ; <i>avec mouv</i>. SOPH. <i>Ph. 377, etc. ;</i><br><b>      2</b> <i>en parl. du temps,</i> en ce moment même, SOPH. <i>O.R. 483 ;</i> XÉN. <i>Cyr. 2, 3, 4</i>.<br><span><b>Étym</b>. ἔνθα, -δε.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενθαδε - ἐνθάδε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G1760":"<h1>enthumeomai</h1>\n<p>Strong n° 1760 <i>Prononciation [en-thoo-meh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amener à l'esprit, réfléchir, ruminer des pensées</li>\n<li>penser, délibérer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·θυμέομαι-οῦμαι</b> <span>[ῡ]</span> <span>(<i>impf</i>. ἐνεθυμούμην, <i>f</i>. ἐνθυμήσομαι, <i>ao</i>. ἐνεθυμήθην, <i>pf</i>. ἐντεθύμημαι, <i>pl.q.pf</i>. ἐνετεθυμήμην)</span> <i>postér</i>. ἐνθυμέω-ῶ :<br><b>   I</b> se mettre dans l’esprit, <i>d’où :</i><br><b>      1</b> réfléchir, penser, <i>joint à</i> λογίζεσθαι, DÉM. <i>15, 7 ;</i> τινος, PLAT. <i>Menex. 249</i> c ; περί τινος, PLAT. <i>Rsp. 595</i> a, réfléchir à qqe ch. ; ὅτι, THC. <i>5, 111 ; ou</i> ὡς, XÉN. <i>Mem. 4, 3, 3,</i> réfléchir que <i>ou</i> comment ; εἰ, ISOCR. <i>332</i> c, réfléchir si, <i>etc. ; avec un partic</i>. οὐκ ἐντεθύμηται ἐπαιρόμενος, THC. <i>1, 120,</i> il n’a pas songé qu’il se laissait emporter (par son ardeur) ; ἐνθ. μή <i>avec le sbj</i>. PLAT. <i>Euthyd. 279</i> c, faire attention que… ne ;<br><b>      2</b> désirer, SPT. <i>Deut. 21, 11 ; en ce sens qqf. au pass. :</i> τὰ ἐνθυμούμενα, APP. <i>Civ. 5, 133,</i> ce qu’on a dans l’esprit, les pensées, les désirs ;<br><b>   II</b> <i>abs</i>. réfléchir, combiner un plan : κράτιστος ἐνθυμηθῆναι, THC. <i>8, 68,</i> très habile à former un plan ;<br><b>   III</b> déduire par un raisonnement : τί οὖν ἐκ τούτων ἐνθυμεῖσθαι δεῖ ; DÉM. <i>532, 2,</i> que faut-il donc conclure de tout cela ?.<br><span><b><span class=\"arrow\"></span></b> <i>Part. prés</i>. ἐνθυμούμενος, <i>au sens pass</i>. APP. (<i>v. ci-dessus). Postér</i>. ἐνθυμέω, EN. TACT. <i>Pol. 37, 3</i>.<br><span><b>Étym</b>. ἐν, θυμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενθυμεομαι - ἐνθυμέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1761":"<h1>enthumesis</h1>\n<p>Strong n° 1761 <i>Prononciation [en-thoo'-may-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une pensée, une considération, réflexion, intention</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνθύμησις, εως (ἡ)</b> <span>[ῡ]</span> réflexion, pensée, HPC. <i>Coac. 26 ;</i> ANT. <i>fr. 248 ;</i> THC. <i>1, 132, etc</i>.<br><span><b>Étym</b>. ἐνθυμέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενθυμησις - ἐνθύμησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Actes (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1762":"<h1>eni</h1>\n<p>Strong n° 1762 <i>Prononciation [en'-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>il y a, est présent</li>\n<li>ce peut être, est possible, est légal</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἐνί</b>, <i>v</i>. .<br><br>\n➁ <b>ἔνι</b>, <i>c</i>. ἔνεστι, <i>v</i>. .<br><br>\n➂ <b>ἑνί</b>, <i>dat. sg. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενι - ἔνι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Galates (3)</li>\n<li>Colossiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1763":"<h1>eniautos</h1>\n<p>Strong n° 1763 <i>Prononciation [en-ee-ow-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une année, dans un sens plus large, une période fixe et définie de temps</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνιαυτός, οῦ (ὁ) :<br>   I</b> <i>litt</i>. objet circulaire en forme d’anneau, <i>particul</i>. sorte de coupe, ATH. <i>783</i> c ;<br><b>   II</b> <i>p. anal. (cf. lat</i>. annus <i>et</i> annulus) évolution du temps, <i>d’où</i> cours périodique du temps, <i>particul. :</i><br><b>      1</b> période astronomique, période de temps déterminée, OD. <i>1, 16 ;</i> HÉS. <i>Th. 493, Sc. 87 ;</i> AR. <i>Ran. 347 ;</i> THC. <i>3, 68 ; en parl. d’une longue période de temps, du cycle de Méton,</i> DS. <i>2, 47 ; 12, 36 ; d’une période (d’un cycle) de 600 ans,</i> JOS. <i>A.J. 1, 3, 9 ; d’une durée illimitée,</i> APD. <i>3, 4, 2 ;</i><br><b>      2</b> <i>particul</i>. année, IL. <i>2, 295, etc. ;</i> ἐνιαυτόν, OD. <i>1, 288,</i> pendant une année ; εἰς ἐνιαυτόν, IL. <i>21, 441, ou</i> κατ' ἐνιαυτόν, THC. <i>1, 93,</i> pour une année ; τοῦ ἐνιαυτοῦ, XÉN. <i>Vect. 4, 33 ;</i> PLAT. <i>Criti. 118</i> e ; ἑκάστου ἐνιαυτοῦ, XÉN. <i>Ath. 3, 4 ;</i> καθ' ἕκαστον ἐνιαυτόν, DIPH. <i>fr. 4,</i> chaque année ; <i>ou simpl. à l’acc</i>. τὸν ἐνιαυτόν, CIA. <i>2, 1055, 1 (345 av. J.C. ; v. Meisterh. p. 166, 7</i>) l’année, par an, chaque année ; μετὰ τὸν ἐνιαυτόν, THC. <i>1, 138,</i> à la fin de l’année ; πρὸ ἐνιαυτοῦ, PLUT. <i>M. 147</i> e, une année avant ; παρ' ἐνιαυτόν, DS. <i>4, 65,</i> par années alternatives ; ἐνιαυτὸν κατ' ἐνιαυτόν, SPT. <i>1Macc. 4, 59,</i> année par année.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. ἐνίαυτος, THCR. <i>Idyl. 30, 24</i>.<br><span><b>Étym</b>. <i>inconnue ; p. le premier terme,</i> ἔνος, année, <i>cf</i>. δίενος, τετράενος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενιαυτος - ἐνιαυτός</font>\n<br><br>prolongation du mot 'enos' (une année)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote une année en tant que cycle ou période de temps\n<br><br> – est une année considérée comme division ou portion de temps</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>Galates (1)</li>\n<li>Hébreux (4)</li>\n<li>Jacques (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1764":"<h1>enistemi</h1>\n<p>Strong n° 1764 <i>Prononciation [en-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre dans ou parmi, mettre</li>\n<li>être proche, menacer, être imminent</li>\n<li>présent</li>\n<li>à portée de main</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·ίστημι :<br>A <i>tr</i>.<br>   I</b> <span>(<i>aux temps suiv. de l’act. : prés., impf., f</i>. ἐνστήσω, <i>ao.1</i> ἐνέστησα)</span> dresser <i>ou</i> établir dans <i>ou</i> sur, placer dans <i>ou</i> sur : στήλας ἐς τὰς χώρας, HDT. <i>2, 102,</i> élever des stèles dans les pays ; ἱπποκόμους εἰς τοὺς ἱππέας, XÉN. <i>Hipp. 5, 6,</i> placer des palefreniers parmi les cavaliers ;<br><b>   II <i>au moy</i>. ἐνίσταμαι</b> <span>(<i>f</i>. ἐνστήσομαι)</span> dresser, élever : ἱστόν, A. RH. <i>1, 563,</i> un mât ; <i>fig</i>. δίκην <i>ou</i> ἀγῶνα, DÉM. <i>227, 3,</i> intenter un procès ; πρᾶγμα, AR. <i>Lys. 268 ;</i> DÉM. <i>137, 2 ;</i> ARSTT. <i>Probl. 29, 13 ;</i> πρᾶξιν, PLUT. <i>Arat. 16,</i> s’engager dans une entreprise ; ὀργὴν καὶ μῖσος πρός τινα, POL. <i>1, 82, 9,</i> commencer à montrer de l’irritation et de la haine contre qqn ; <i>avec un inf</i>. DS. <i>14, 53,</i> entreprendre de faire qqe ch. ;<br><b>B <i>intr.</i></b> <span>(<i>au moy. et aux temps suiv. de l’act. : ao.2</i> ἐνέστην, <i>pf</i>. ἐνέστηκα <i>et</i> ἐνέσταα)</span><br><b>   I</b> s’établir dans : λόχοις, EUR. <i>Suppl. 896</i> (ἐφεστώς <i>Blomf</i>.) se poster au milieu de l’armée ; εἰς τὴν ἄρχην, HDT. <i>3, 68,</i> prendre possession du pouvoir ; τοῦ ἐνεστῶτος μηνός, PHILIPP. (DÉM. <i>280, 12</i>) le mois commencé ; <i>p. suite au pf</i>. avoir pris de la consistance, être consistant, <i>en parl. d’un liquide congelé,</i> TH. <i>C.P. 5, 13, 1, ou de lait caillé,</i> DIOSC. <i>Iob. 26 ; fig</i>. se trouver établi, se trouver : τὰ ἐνεστηκότα πράγματα, XÉN. <i>Hell. 2, 1, 6 ;</i> τὰ ἐνεστῶτα, POL. <i>2, 26, 3,</i> les affaires présentes ; ὁ ἐνστὰς πόλεμος, DÉM. <i>255, 10 ; ou</i> ὁ ἐνεστὼς πόλεμος, ESCHN. <i>35, 27,</i> la guerre actuelle (<i>mais v. ci-dessous</i>) ; ὁ ἐνεστὼς βασιλεύς, POL. <i>18, 38, 5,</i> le roi régnant ; <i>t. de gramm</i>. ὁ ἐνεστὼς χρόνος, D. THR. <i>638, 22 ;</i> PLUT. <i>M. 1081</i> d, <i>etc</i>. le présent d’un verbe ;<br><b>   II</b> se dresser au-devant de <i>ou</i> contre, <i>d’où :</i><br><b>      1</b> s’opposer à : τινί, THC. <i>8, 69 ;</i> ISOCR. <i>90</i> a ; DÉM. <i>1274, 20 ;</i> POL. <i>2, 46, 4,</i> à qqn <i>ou</i> à qqe ch. ; πρός τι, PLUT. <i>Rom. 25,</i> à qqe ch. ; <i>abs</i>. LYS. <i>97, 10 ; particul. en parl. des tribuns du pple, à Rome,</i> POL. <i>6, 16, 4, etc. ;</i><br><b>      2</b> <i>p. suite,</i> menacer, être imminent <i>ou</i> pressant, presser, <i>avec le dat</i>. τὸν πόλεμον τὸν ἐνστάντα τῇ πόλει, ISOCR. <i>82</i> b, la guerre qui menaçait la république ; <i>cf</i>. HDT. <i>1, 83 (mais v. ci-dessus, B, I) ;</i><br><b>      3</b> <i>d’où</i> poursuivre, serrer de près : τινί, POL. <i>3, 97, 1,</i> qqn ; τῇ φυγῇ, PLUT. <i>Luc. 13,</i> serrer qqn de près dans sa fuite.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. 3 pl. ion</i>. ἐνεστέασι, HDT. <i>1, 179</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενιστημι - ἐνίστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1765":"<h1>enischuo</h1>\n<p>Strong n° 1765 <i>Prononciation [en-is-khoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>devenir fort, recevoir la force</li>\n<li>rendre fort, fortifier</li>\n<li>réconforter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·ισχύω :<br>      1 <i>intr.</i></b> avoir <i>ou</i> prendre de la force dans, <i>dat</i>. ARSTT. <i>Nic. 10, 9, 14 ;</i> TH. <i>fr. 1, 65 ; abs</i>. ARSTT. <i>P.A. 2, 7, 17 ;</i> TH. <i>C.P. 5, 9, 3 ;</i> ἐνίσχυσεν ὡς, DS. <i>5, 57,</i> cette croyance s’affermit dans les esprits que, <i>etc. ;</i><br><b>      2 <i>tr.</i></b> fortifier, HPC. <i>Lex. 2, 26</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενισχυω - ἐνισχύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1766":"<h1>ennatos</h1>\n<p>Strong n° 1766 <i>Prononciation [en'-nat-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>neuvième\n<ol type=\"a\">\n<li>la neuvième heure correspond à 3 heures de l'après-midi car la sixième heure des Juifs correspond à midi selon notre méthode de division du temps. Leur première heure du jour est 6 heures du matin pour nous</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνατος, η, ον</b> <span>[ᾰ]</span> neuvième, IL. <i>2, 313, etc. ;</i> HÉS. <i>O. 8, etc</i>. τὰ ἔνατα (<i>s.-e</i>. ἱερά), IS. <i>73, 25 ;</i> ESCHN. <i>86, 5,</i> sacrifice qu’on célébrait neuf jours après la mort de qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. εἴνατος, IL. <i>2, 295 ; 8, 266, etc. ; dans les inscr. att. touj</i>. ἔνατος (<i>non</i> ἔννατος) CIA. <i>1, 188, 15 (410 av. J.C.) etc. ; v. Meisterh. p. 126, note 1123</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννατος - ἔνατος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1767":"<h1>ennea</h1>\n<p>Strong n° 1767 <i>Prononciation [en-neh'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>neuf</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐννέα</b> <span>[ᾰ]</span> (οἱ, αἱ, τὰ) <i>indécl</i>. neuf, IL. <i>2, 96, etc. ;</i> OD. <i>3, 7, etc. ;</i> ATT. <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. ἔννεα, THCR. <i>Idyl. 30, 27</i>.<br><span><b>Étym</b>. <i>pour</i> *ἐννέϝα, <i>de indo-europ</i>. *h₁n(e)un, neuf ; <i>cf. lat</i>. nŏvem, <i>sscr</i>. náva, <i>all</i>. neun.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννεα - ἐννέα</font>\n<br><br>nombre primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nombre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)\n<ul type=\"square\">\n<li>Luc 17.17</li>\n</ul>\n</li>\n</ul>\n</td></tr>\n</table>","G1768":"<h1>ennenekontaennea</h1>\n<p>Strong n° 1768 <i>Prononciation [en-nen-ay-kon-tah-en-neh'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>quatre-vingt-dix neuf</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνενηκοντα·εννέα</b>, <i>n. de n. indécl</i>. quatre-vingt-dix-neuf, SPT. <i>Gen. 17, 1</i>.<br><span><b>Étym</b>. ἐ. ἐννέα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννενηκονταεννεα - ἐνενήκονταεννεα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nombre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G1769":"<h1>enneos</h1>\n<p>Strong n° 1769 <i>Prononciation [en-neh-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>muet, privé du pouvoir de parler</li>\n<li>incapable de parler par terreur, devenu muet, stupéfait</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνεός</b> <i>ou</i> <b>ἐννεός, ά, όν :<br>   I</b> muet de naissance, <i>d’ord. joint à</i> κωφός « sourd » XÉN. <i>An. 4, 5, 33 ;</i> PLAT. <i>Theæt. 206</i> d ; ARSTT. <i>H.A. 4, 9, 16 ; Probl. 33, 1, etc. ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> muet de stupeur <i>ou</i> d’effroi, EUM. <i>6, 10 ;</i><br><b>      2</b> <i>p. suite,</i> stupide, imbécile, PLAT. <i>2 Alc. 140</i> d ;<br><b>      3</b> <i>en parl. de choses,</i> qui ne peut être d’aucun usage, HPC. <i>743</i> c.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννεος - ἐννεός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1770":"<h1>enneuo</h1>\n<p>Strong n° 1770 Prononciation [en-nyoo'-o]</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>incliner la tête, signifier ou exprimer par un signe de la tête</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·νεύω</b>, faire un signe, LUC. <i>D. mer. 12, 1 ;</i> τινί τι, NT. <i>Luc. 1, 62,</i> faire qqe signe à qqn ; <i>avec la prop. inf</i>. AR. <i>fr. 58,</i> faire signe que.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννευω - ἐννεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1771":"<h1>ennoia</h1>\n<p>Strong n° 1771 <i>Prononciation [en'-noy-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'action de penser, considération, méditation</li>\n<li>une pensée, une notion, une conception</li>\n<li>esprit, compréhension, volonté, manière de voir et de penser, opinion</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔννοια, ας (ἡ) :<br>   I</b> l’acte de penser, exercice de la pensée, PLAT. <i>Leg. 657</i> a ;<br><b>   II.1</b> conception, notion, intelligence, PLAT. <i>Phil. 59</i> d ; χρόνου, PLAT. <i>Tim. 47</i> a, la conception du temps : ἔννοιαν λαϐεῖν, PLAT. <i>Phæd. 73</i> c, se former une notion (dans l’esprit) <i>p. opp. à</i> ἐπιστήμην ἔχειν ; εἰς ἔννοιαν ἔρχεσθαί τινος, POL. <i>1, 57, 4,</i> en arriver à concevoir qqe ch. ; <i>en parl. d’un mot,</i> signification <i>ou</i> sens, DC. <i>69, 21 ;</i><br><b>      2</b> réflexion, pensée, idée, XÉN. <i>An. 3, 1, 13 ;</i> PLUT. <i>M. 585</i> f, <i>etc. ;</i> ἔννοιαν λαϐεῖν τινος, EUR. <i>Hipp. 1027, ou</i> ἔχειν περί τι, PLAT. <i>Leg. 769</i> e, faire une réflexion <i>ou</i> avoir une pensée sur qqe ch. ; ἔννοιαν ἐμποιεῖν, ISOCR. <i>112</i> d, se mettre une idée dans l’esprit ; <i>particul. t. de rhét</i>. pensée, sentence, HERMOG. <i>π. ἰδ. 3, p. 330, 15 ;</i><br><b>      3</b> <i>p. ext</i>. raison, bon sens : παρὰ τὴν ἔννοιαν, PLUT. <i>M. 1077</i> c, contrairement à la raison.<br><span><b>Étym</b>. ἔννοος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννεοια - ἔννοια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1772":"<h1>ennomos</h1>\n<p>Strong n° 1772 <i>Prononciation [en'-nom-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lié à la loi</li>\n<li>lié par la loi, légal</li>\n<li>régulier</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nἔν·νομος, ος, ον :<br>   I</b> conforme à la loi :<br><b>      1</b> réglé par la loi, légal, légitime, PD. <i>O. 7, 155, etc. ;</i> ἔνν. πολιτεία, ESCHN. <i>1, 25,</i> gouvernement légal ; ἔννομα πάσχειν, THC. <i>3, 67,</i> subir un châtiment réglé par la loi ;<br><b>      2</b> qui se conforme aux lois, juste, ESCHL. <i>Suppl. 404 ;</i> PLAT. <i>Rsp. 424</i> e ; <i>particul</i>. conforme à la loi (de Moïse) SPT. <i>Sir. prol. ;</i> CLÉM. <i>2, 624 Migne ;</i><br><b>   II</b> bien réglé, mesuré, harmonieux, LUC. <i>Salt. 2</i>.<br><span>•<i> Cp</i>. -ώτερος, ARSTT. <i>Rhet. Al. 37 ;</i> <i>• Sup</i>. -ώτατος, XÉN. <i>Hell. 2, 3, 52</i>.<br><span><b>Étym</b>. ἐν, νόμος.</span>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ἔν·νομος, ος, ον :<br>   I</b> conforme à la loi :<br><b>      1</b> réglé par la loi, légal, légitime, PD. <i>O. 7, 155, etc. ;</i> ἔνν. πολιτεία, ESCHN. <i>1, 25,</i> gouvernement légal ; ἔννομα πάσχειν, THC. <i>3, 67,</i> subir un châtiment réglé par la loi ;<br><b>      2</b> qui se conforme aux lois, juste, ESCHL. <i>Suppl. 404 ;</i> PLAT. <i>Rsp. 424</i> e ; <i>particul</i>. conforme à la loi (de Moïse) SPT. <i>Sir. prol. ;</i> CLÉM. <i>2, 624 Migne ;</i><br><b>   II</b> bien réglé, mesuré, harmonieux, LUC. <i>Salt. 2</i>.<br><span>•<i> Cp</i>. -ώτερος, ARSTT. <i>Rhet. Al. 37 ;</i> <i>• Sup</i>. -ώτατος, XÉN. <i>Hell. 2, 3, 52</i>.<br><span><b>Étym</b>. ἐν, νόμος.</span><br><br>\n➁ <b>ἔν·νομος, ος, ον</b>, qui habite (<i>litt</i>. qui paît) dans, habitant, ESCHL. <i>Suppl. 565</i>.<br><span><b>Étym</b>. ἐν, νέμομαι.</span>\n</td></tr>\n</table>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννομος - ἔννομος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1773":"<h1>ennuchon</h1>\n<p>Strong n° 1773 <i>Prononciation [en'-noo-khon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>nocturne, de nuit</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔν·νυχος, ος, ον</b> <span>[ῠ]</span> qui vit <i>ou</i> agit dans les ténèbres, IL. <i>11, 716 ;</i> ESCHL. <i>Pr. 645 ; adv</i>. ἔννυχον, ES. <i>110 Halm. ;</i> NT. <i>Marc. 1, 35</i> (ἔννυχα <i>Lachm</i>.) pendant la nuit.<br><span>•<i> Cp</i>. ώτερον, ES. NT. <i>ll. cc</i>.<br><span><b>Étym</b>. ἐν, νύξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εννυχον - ἔννυχον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G1774":"<h1>enoikeo</h1>\n<p>Strong n° 1774 <i>Prononciation [en-oy-keh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demeurer en</li>\n<li>métaph. habiter dans quelqu'un et l'influencer (pour le bien)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·οικέω-ῶ :<br>      1</b> habiter dans, <i>dat</i>. EUR. <i>H.f. 1282 ;</i> ἐν <i>avec le dat</i>. XÉN. <i>An. 5, 6, 25 ; fig</i>. ἐν τοῖς φυσικοῖς, ARSTT. <i>Gen. et corr. 1, 2, 10,</i> vivre dans l’étude de la nature ;<br><b>      2</b> <i>p. ext</i>. habiter, <i>en gén., acc</i>. HDT. <i>1, 4 ; 2, 178 ;</i> SOPH. <i>O.C. 1533,</i> une ville ; οἱ ἐνοικοῦντες, HDT. <i>2, 66 ;</i> THC. <i>1, 18, etc</i>. les habitants.<br><span><b><span class=\"arrow\"></span></b> ἐνοικέω <i>trisyll. par syniz</i>. THCR. <i>Idyl. 9, 15</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενοικεω - ἐνοικέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G1775":"<h1>henotes</h1>\n<p>Strong n° 1775 <i>Prononciation [hen-ot-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>unité</li>\n<li>unanimité, accord</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἑνότης, ητος (ἡ) :<br>      1</b> unité, ARSTT. <i>Metaph. 4, 9, 3, etc. ;</i><br><b>      2</b> <i>p. suite,</i> union, NT. <i>Eph. 4, 3, 13 ;</i> PLUT. <i>M. 769</i> f ; CLÉM. <i>1, 200 Migne</i>.<br><span><b>Étym</b>. εἷς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενοτης - ἑνότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (2)</li>\n</ul>\n</td></tr>\n</table>","G1776":"<h1>enochleo</h1>\n<p>Strong n° 1776 <i>Prononciation [en-okh-leh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>exciter, dérangement, déranger, contrarier, ennuyer, troubler, tourmenter</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·οχλέω-ῶ</b> <span>(<i>impf</i>. ἠνώχλουν, <i>f</i>. ἐνοχλήσω, <i>ao</i>. ἠνώχλησα, <i>pf</i>. ἠνώχληκα ; <i>pass. f</i>. ἐνοχληθήσομαι, <i>ao</i>. ἠνωχλήθην, <i>pf. inus</i>.)</span> causer de la gêne, gêner, troubler, <i>avec le dat</i>. XÉN. <i>An. 2, 5, 13 ; 3, 4, 21 ;</i> ISOCR. <i>42</i> c ; DÉM. <i>30, 6 ; rar. l’acc</i>. XÉN. <i>Mem. 3, 8, 2 ;</i> PLAT. <i>1 Alc. 104</i> d ; <i>avec un acc. neutre :</i> ὅσα ἠνώχλησεν, DÉM. <i>519, 15,</i> tout le trouble qu’il a causé ; <i>avec un part</i>. ἠνώχλει λέγων, XÉN. <i>Cyr. 5, 3, 36,</i> il causait du trouble en disant, <i>etc. ; au pass</i>. être troublé, gêné, XÉN. <i>Cyr. 5, 4, 34 ;</i> DÉM. <i>347, 18 ;</i> ESCHN. <i>59, 39</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Part. f. moy. au sens pass</i>. ἐνοχλησόμενος, APP. <i>Civ. 1, 36 ;</i> GAL. <i>3, 933. Act. prés. 2 sg. éol</i>. ἐνόχλης (<i>var</i>. ἐνοχλεῖς ; <i>sel. d’autres,</i> ἐννοχλεῖς) <span>[ε̄ο̆]</span> THCR. <i>Idyl. 29, 36</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενοχλεω - ἐνοχλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1777":"<h1>enochos</h1>\n<p>Strong n° 1777 <i>Prononciation [en'-okh-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lié, sous une obligation, sujet à, responsable de\n<ol type=\"a\">\n<li>de celui qui est tenu par, possédé par l'amour, zélé pour quelque chose</li>\n<li>dénote le lien d'une personne, soit avec son crime, soit avec sa peine, soit avec ce qu'il a offensé\n<ol>\n<li>coupable, mérite la punition</li>\n<li>coupable de quelque chose</li>\n<li>un crime</li>\n<li>une pénalité</li>\n<li>passible d'un tribunal c.à.d que la punition sera imposée par tel ou tel tribunal</li>\n<li>le lieu où la punition est subie</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνοχος, ος, ον :<br>   I</b> <i>au propre,</i> qui tient à, fixé dans, <i>en parl. d’une ancre,</i> ANTH. <i>7, 50, 6, 3 ;</i><br><b>   II</b> <i>fig</i>. tenu dans <i>ou</i> par, <i>d’où :</i><br><b>      1</b> assujetti à, asservi à : δόξαις, ARSTT. <i>Metaph. 3, 5, 10,</i> à des opinions ; <i>particul. en parl. d’obligations légales :</i> νόμῳ, PLAT. <i>Leg. 869</i> b, asservi à la loi ; ἀραῖς, DÉM. <i>404, 4 ;</i> ζημίαις, LYS. <i>14, 9 Baiter-Sauppe,</i> sous le coup d’anathèmes, d’amendes ;<br><b>      2</b> exposé à, <i>avec le gén. :</i> ἐν. θανάτου, DS. <i>Exc. 571, 14,</i> passible de la peine de mort ; <i>particul</i>. exposé à une accusation, accusé de : φόνῳ, ANT. <i>112, 38 ;</i> ARSTT. <i>Pol. 2, 8, 20,</i> de meurtre ; <i>avec le gén</i>. τῶν βιαίων, PLAT. <i>Leg. 914</i> e, de violence ; <i>qqf. avec une prép. :</i> ἔν τινι, AND. <i>11, 5,</i> περί τινος, PHILIPP. (DÉM. <i>239, 4</i>) accusé de qqe ch.<br><span><b>Étym</b>. ἐνέχω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενοχος - ἔνοχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 8 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1778":"<h1>entalma</h1>\n<p>Strong n° 1778 <i>Prononciation [en'-tal-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un précepte, ordre, commandement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔνταλμα, ατος (τὸ)</b> commandement, précepte, SPT. <i>Esaï. 29, 13 ; Job 23, 12 ;</i> NT. <i>Matth. 15, 9</i>.<br><span><b>Étym</b>. ἐντέλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενταλμα - ἔνταλμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1779":"<h1>entaphiazo</h1>\n<p>Strong n° 1779 <i>Prononciation [en-taf-ee-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>préparer un corps à la sépulture, par tout ce que nécessitent les funérailles : vêtements, fleurs, couronnes, parfums, libations, etc.</li>\n<li>ensevelir un corps, mettre au tombeau</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·ταφιάζω</b> <span>[τᾰ]</span> préparer l’ensevelissement, ANTH. <i>11, 125 ;</i> PLUT. <i>M. 995</i> c ; SPT. <i>Gen. 50, 2 ;</i> NT. <i>Matth. 26, 12 ; Joh. 19, 40</i>.<br><span><b>Étym</b>. ἐντάφιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενταφιαζω - ἐνταφιάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1780":"<h1>entaphiasmos</h1>\n<p>Strong n° 1780 <i>Prononciation [en-taf-ee-as-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>préparation d'un corps pour la sépulture</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνταφιασμός, οῦ (ὁ)</b> <span>[τᾰ]</span> ensevelissement, NT. <i>Marc. 14, 8 ; Joh. 12, 7</i>.<br><span><b>Étym</b>. ἐνταφιάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενταφιασμος - ἐνταφιασμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1781":"<h1>entellomai</h1>\n<p>Strong n° 1781 <i>Prononciation [en-tel'-lom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ordonner, commander de faire, enjoindre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντελλομαι - ἐντέλλομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 17 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Luc (1)</li>\n<li>Jean (5)</li>\n<li>Actes (2)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G1782":"<h1>enteuthen</h1>\n<p>Strong n° 1782 <i>Prononciation [ent-yoo'-then]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>depuis ce lieu, d'ici, de là</li>\n<li>d'un côté et de l'autre, de chaque côté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐντεῦθεν</b>, <i>adv. :</i><br><b>   I</b> (<i>lieu</i>) :<br><b>      1</b> d’ici, de là, OD. <i>19, 568 ;</i> HDT. <i>1, 2, etc. ;</i> ESCHL. <i>Pr. 836 ;</i><br><b>      2</b> <i>p. suite, c</i>. ἐνταῦθα, là : τἀντεῦθεν, SOPH. <i>El. 1339,</i> les choses de là, <i>càd</i>. ce qui se passe dans cette maison ; ἐντεῦθεν καὶ ἐντεῦθεν, SPT. <i>Num. 22, 24 ;</i> NT. <i>Joh. 19, 18 ; Apoc. 22, 2,</i> d’un côté et de l’autre ;<br><b>   II</b> (<i>temps</i>) à partir de maintenant, dès à présent, SOPH. <i>El. 728, Ph. 834 ;</i> τὸ ἐντεῦθεν, HDT. <i>1, 9, 27, etc. ; d’où</i> τοὐντεῦθεν, EUR. <i>Med. 792 ;</i> τὰ ἐντεῦθεν, <i>d’où</i> τἀντεῦθεν, ESCHL. <i>Eum. 60,</i> dès à présent, désormais ;<br><b>   III</b> (<i>origine ou cause</i>) de là, de cette source, THC. <i>1, 5 ;</i> ARSTT. <i>Nic. 5, 3, 6 ; d’où</i> par suite de cela, en conséquence, EUR. <i>Andr. 949 ;</i> PLAT. <i>Crat. 399</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. ἐνθεῦτεν, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. ἐνταῦθα, -θεν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντευθεν - ἐντεῦθεν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (3)</li>\n<li>Jean (6)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1783":"<h1>enteuxis</h1>\n<p>Strong n° 1783 <i>Prononciation [ent'-yook-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une rencontre avec\n<ol type=\"a\">\n<li>une entrevue\n<ol>\n<li>venir ensemble</li>\n<li>visiter</li>\n<li>converser</li>\n</ol>\n</li>\n<li>ce pour quoi l'entrevue est faite\n<ol>\n<li>conférence ou conversation</li>\n<li>requête, supplication, demande</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔντευξις, εως (ἡ) :<br>   I</b> action de rencontrer : τινι, PLAT. <i>Pol. 298</i> d, qqn, rencontre de qqn ; <i>p. suite :</i><br><b>      1</b> entrevue, entretien, conférence : τινος, ESCHN. <i>34, 19 ;</i> πρός τινα, ARSTT. <i>Rhet. 1, 1, 12,</i> avec qqn ; ἐντεύξεις ποιεῖσθαί τινι, ISOCR. <i>6</i> b ; POL. <i>5, 35, 4,</i> s’aboucher avec qqn, avoir des entrevues, une entrevue avec lui ; <i>particul</i>. relations intimes, PLUT. <i>M. 655</i> b ;<br><b>      2</b> discours : ἐντ. ὀχλική, DH. <i>Thuc. 50,</i> discours à la foule ;<br><b>      3</b> <i>p. ext</i>. requête, demande, POL. <i>5, 61, 1 ;</i> DS. <i>16, 55 ;</i> PLUT. <i>T. Gracch. 11, M. 530</i> a ; JOS. <i>A.J. 16, 2, 5 ;</i> NT. <i>1Tim. 2, 1 ; 4, 5 ;</i><br><b>   II</b> lecture, POL. <i>1, 1, 4 ; 9, 1, 3 ;</i> CLÉM. <i>2, 469 Migne</i>.<br><span><b>Étym</b>. ἐντυγχάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντευξις - ἔντευξις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> a un sens de pétition,  est un mot de caractère sacré, étant limité à la prière à Dieu, tandis que  peut aussi être utilisé pour une requête adressée à un homme.  exprime un accès à Dieu en se confiant à lui,  donne la prééminence à l'expression de besoin personnel,  à l'élément de dévotion,\n<br><br> à celle de confiance telle celle d'un enfant, en représentant la prière comme une conversion du cœur qui s'est tourné vers Dieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G1784":"<h1>entimos</h1>\n<p>Strong n° 1784 <i>Prononciation [en'-tee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tenu en honneur, considéré, précieux, estimé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔν·τιμος, ος, ον</b> <span>[ῑ]</span><br><b>   I</b> <i>pass. :</i><br><b>      1</b> qui a de la valeur, <i>en parl. d’une monnaie,</i> PLAT. <i>Leg. 742</i> a ;<br><b>      2</b> <i>fig</i>. estimé, considéré, honoré, <i>p. opp. à</i> ἔκτιμος, PLAT. <i>Euthyd. 281</i> c ; ἔντ. τινι, SOPH. <i>Ant. 25, El. 239,</i> honoré par qqn ; παρά τινι, PLAT. <i>Rsp. 554</i> b, en honneur auprès de qqn ; οἱ ἔντιμοι, les gens honorables, <i>p. opp. à</i> ἄδοξοι, DÉM. <i>36, 21 ; ou absol.,</i> DÉM. <i>1380, 25 ; ou</i> les gens de haut rang, les personnages de distinction, <i>chez les Perses,</i> XÉN. <i>Cyr. 3, 1, 8 ;</i> τὰ τῶν θεῶν ἔντιμα, SOPH. <i>Ant. 77,</i> le respect dû aux dieux ;<br><b>   II</b> <i>act</i>. qui témoigne de la considération, qui honore, PLAT. <i>Leg. 855</i> a.<br><span>•<i> Cp</i>. -ότερος, XÉN. <i>An. 6, 3, 11 ; Mem. 2, 1, 27, etc. ;</i> PLAT. <i>Phædr. 244</i> d, <i>Leg. 727</i> e, <i>etc. ;</i> ARSTT. <i>Rhet. 2, 15 ; Meteor. 1, 14, etc.</i> <i>• Sup</i>. -ότατος, XÉN. <i>Ages. 1, 2 ; Hell. 6, 1, 4 ;</i> PLAT. <i>Ep. 355</i> b ; ARSTT. <i>Nic. 1, 1 ; 4, 5 ;</i> EL. TACT. <i>22</i>.<br><span><b>Étym</b>. ἐν, τιμή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντιμος - ἔντιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Philippiens (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G1785":"<h1>entole</h1>\n<p>Strong n° 1785 <i>Prononciation [en-tol-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un ordre, une commande, un précepte, une injonction\n<ol type=\"a\">\n<li>ce qui est prescrit à quelqu'un en raison de sa fonction</li>\n</ol>\n</li>\n<li>un commandement\n<ol type=\"a\">\n<li>règle prescrite en accord avec ce qui se fait\n<ol>\n<li>précepte relatif à la lignée, le précepte Mosaïque concernant les sacrificateurs</li>\n<li>utilisé pour les commandements de la loi Mosaïque ou la tradition Juive</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐντολή, ῆς (ἡ)</b> ordre, instruction, HDT. <i>1, 157 ;</i> LUC. <i>Im. 16, etc. ;</i> SPT. <i>Deut. 4, 2 ; 4Reg. 21, 8 ;</i> NT. <i>Ap. 17, 15 ; Joh. 11, 57, etc. ; plur. au sens du sg</i>. PD. <i>fr. 167 ;</i> HDT. <i>1, 22 ; 3, 147, etc</i>.<br><span><b>Étym</b>. ἐντέλλω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντολη - ἐντολή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n68 fois dans 62 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (6)</li>\n<li>Luc (4)</li>\n<li>Jean (10)</li>\n<li>Actes (1)</li>\n<li>Romains (7)</li>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (2)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (4)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (14)</li>\n<li>2 Jean (4)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1786":"<h1>entopios</h1>\n<p>Strong n° 1786 <i>Prononciation [en-top'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>qui habite dans un lieu</li>\n<li>qui réside ou qui est natif d'un lieu, originaire du pays</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐντόπιος, ος, ον</b>, local, du pays : ἐντόπιοι θεοί, PLAT. <i>Phædr. 262</i> d, dieux indigètes ; ἐ. πόλεμοι, DH. <i>8, 83,</i> guerres civiles.<br><span><b>Étym</b>. ἔντοπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντοπιος - ἐντόπιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1787":"<h1>entos</h1>\n<p>Strong n° 1787 <i>Prononciation [en-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dedans, à l'intérieur de\n<ol type=\"a\">\n<li>au milieu de vous</li>\n<li>votre âme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐντός</b>, <i>adv. et prép</i>. à l’intérieur, <i>d’où :</i><br><b>   I</b> en dedans, à l’intérieur : τὰ ἐντός, l’intérieur du corps, THC. <i>2, 49 ;</i> PLAT. <i>Prot. 334</i> c ; <i>ou fig</i>. ce qui est intérieur dans l’homme, <i>càd</i>. l’intelligence, la réflexion, <i>etc</i>. SPT. <i>Ps. 102, 2 ;</i> ἐντὸς ποιεῖσθαι, THC. <i>2, 83 ; 6, 67, 75 ;</i> XÉN. <i>An. 7, 8, 16 ; ou</i> ποιεῖν, THC. <i>5, 2 ; 7, 5,</i> recevoir à l’intérieur (d’une enceinte, d’une troupe, <i>etc</i>.) ; ἐντὸς ἑωυτοῦ γίνεσθαι, HDT. <i>1, 119,</i> redevenir maître de soi ; <i>abs</i>. ἐντὸς εἶναι, DÉM. <i>13, 18,</i> être maître de soi (<i>p. opp. à</i> ἐκτός, hors de soi) ; ἐντ. λογισμῶν εἶναι, PLUT. <i>Alex. 32,</i> être dans son bon sens ; <i>avec mouv</i>. ἐντὸς ἰέναι, IL. <i>12, 374 ;</i> πέμπειν, EUR. <i>Tr. 12,</i> aller, envoyer à l’intérieur de, <i>etc. ;</i><br><b>   II</b> en arrière <i>ou</i> en retrait (<i>p. opp. à</i> ἐκτός, en avant <i>ou</i> en saillie) : τὸ ἐντός, l’arrière-champ (d’une machine de jet) HÉRON ; ἐντὸς τείχεος, IL. <i>12, 380,</i> en arrière <i>ou</i> en dedans du mur ;<br><b>   III</b> <i>p. suite,</i> en deçà : ἐντὸς τοξεύματος, EUR. <i>H.f. 991 ;</i> XÉN. <i>Cyr. 1, 4, 23,</i> en deçà du trait ; ἐντὸς τοῦ ποταμοῦ, HDT. <i>1, 6 ;</i> THC. <i>1, 16,</i> en deçà du fleuve ; <i>p. anal. en parl. du temps :</i> ἐντὸς ἑσπέρας, XÉN. <i>Cyn. 4, 11,</i> jusqu’au soir et pas plus tard ; <i>avec un n. de nombre :</i> ἐντὸς εἴκοσιν ἡμερῶν, THC. <i>4, 39 ;</i> ἐντὸς τριάκοντα ἡμερῶν, CIA. <i>1, 57, b, 2, 14 (411 av. J.C. ; v. Meisterh. p. 167, 14</i>), en moins de vingt, de trente jours ; ἐντὸς δραχμῶν πεντήκοντα, PLAT. <i>Leg. 953</i> b, une somme de moins de cinquante drachmes ; <i>en parl. de la parenté :</i> ἐντὸς ἀνεψιότητος, PLAT. <i>Leg. 871</i> b ; DÉM. <i>1668 fin, litt</i>. parenté de cousins plus proches que des cousins ordinaires, <i>càd</i>. parenté de cousins germains.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντος - ἐντός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1788":"<h1>entrepo</h1>\n<p>Strong n° 1788 <i>Prononciation [en-trep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire honte à</li>\n<li>être honteux, faire rentrer en soi-même, éprouver un sentiment de honte</li>\n<li>respecter une personne</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·τρέπω :<br>      1</b> retourner : τὰ νῶτα, HDT. <i>7, 211,</i> tourner le dos pour fuir ;<br><b>      2</b> changer, LUC. <i>H. conscr. 15 ; particul</i>. amener à d’autres sentiments, EL. <i>V.H. 3, 17 ;</i> DL. <i>2, 29 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> rentrer en soi-même, réfléchir, hésiter, POL. <i>31, 12, 6 ;</i><br><b>      2</b> se laisser émouvoir <i>ou</i> attendrir, IL. <i>15, 554 ;</i><br><b>      3</b> se préoccuper : τινος, SOPH. <i>O.R. 1226, etc. ;</i> PLAT. <i>Crit. 52</i> c, <i>etc</i>. au sujet de qqn <i>ou</i> de qqe ch. ; <i>avec l’inf</i>. se préoccuper de faire qqe ch. THGN. <i>400 Bkk. ;</i><br><b>      4</b> éprouver un sentiment de crainte <i>ou</i> de respect devant, <i>acc</i>. SPT. <i>Job 32, 21 ; Sap. 2, 10 ;</i> NT. <i>Matth. 21, 37 ; Luc. 18, 2 ;</i><br><b>      5</b> éprouver un sentiment de honte, SPT. <i>Num. 12, 14</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντρεπω - ἐντρέπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1789":"<h1>entrepho</h1>\n<p>Strong n° 1789 <i>Prononciation [en-tref'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>nourrir</li>\n<li>métaph. instruire, former l'esprit</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·τρέφω</b> <span>(<i>f</i>. -θρέψω)</span> nourrir dans, <i>dat</i>. ANTH. <i>9, 231 ; abs</i>. τέκνα, EUR. <i>Ion 1428,</i> élever des enfants ; <i>au pass</i>. être nourri <i>ou</i> élevé dans (les gymnases, dans certaines habitudes), <i>dat</i>. EUR. <i>Ph. 368 ;</i> PLAT. <i>Leg. 798</i> a ; PLUT. <i>M. 32</i> e ;<br><b><i>Moy.</i></b> nourrir, élever : φυτά, HÉS. <i>O. 779,</i> des plantes ; <i>fig</i>. PLUT. <i>M. 38</i> b.<br><span><b><span class=\"arrow\"></span></b> <i>Épq</i>. ἐνιτρέφω, A. RH. <i>3, 528</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντρεφω - ἐντρέφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1790":"<h1>entromos</h1>\n<p>Strong n° 1790 <i>Prononciation [en'-trom-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tremblant, terrifié, effrayé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἔν·τρομος, ος, ον</b>, tout tremblant, PLUT. <i>Fab. 3 ;</i> ANTH. <i>5, 204 ;</i> SPT. <i>Ps. 76, 19 ; 1 Macc. 13, 2</i>.<br><span><b>Étym</b>. ἐν, τρέμω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντρομος - ἔντρομος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1791":"<h1>entrope</h1>\n<p>Strong n° 1791 <i>Prononciation [en-trop-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>honte, confusion</li>\n<li>respect, révérence</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐντροπή, ῆς (ἡ)</b> action de se retourner :<br><b>      1</b> changement de dispositions, de sentiments, POL. <i>4, 52, 2 ;</i><br><b>      2</b> action de rentrer en soi-même par honte <i>ou</i> par crainte, pudeur, confusion, HPC. <i>23, 34 ;</i> SPT. <i>Ps. 34, 26 ; 68, 8 et 20 ;</i> NT. <i>1Cor. 6, 5 ; 15, 34 ; p. suite,</i> respect, SOPH. <i>O.C. 299</i>.<br><span><b>Étym</b>. ἐντρέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντροπη - ἐντροπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G1792":"<h1>entruphao</h1>\n<p>Strong n° 1792 <i>Prononciation [en-troo-fah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vivre dans le luxe, vivre délicatement ou luxueusement, vivre d'une vie sensuelle</li>\n<li>prendre plaisir à, se complaire dans, faire ses délices</li>\n<li>se jouer, se railler</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐντρυφάω-ῶ</b> <span>[ῠ]</span><br><b>      1</b> faire ses délices de, se complaire dans : τινι, DS. <i>19, 71 ;</i> ἔν τινι, DC. <i>65, 20 ;</i> NT. <i>2Petr. 2, 13,</i> dans qqe ch. ; <i>fig</i>. se jouer avec : ἀνέμοις, CHÆRÉM. (ATH. <i>608</i> e) avec le vent, <i>en parl. d’une chevelure ; abs</i>. s’adonner à la mollesse, XÉN. <i>Hell. 4, 1, 30 ;</i><br><b>      2</b> se jouer, se railler de, <i>dat</i>. EUR. <i>Cycl. 588 ;</i> LUC. <i>M. cond. 35 ; d’où au pass</i>. être raillé, insulté, PLUT. <i>Lys. 6, Cæs. 64</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντρυφαω - ἐντρυφάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1793":"<h1>entugchano</h1>\n<p>Strong n° 1793 <i>Prononciation [en-toong-khan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aller vers, rencontrer une personne dans un but de conversation, consultation, ou supplication</li>\n<li>prier, supplier</li>\n<li>intercéder pour quelqu'un</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·τυγχάνω</b> <span>(<i>f</i>. -τεύξομαι)</span><br><b>   I</b> rencontrer par hasard, <i>d’où :</i><br><b>      1</b> <i>avec un suj. de pers</i>. trouver sur son chemin ; <i>avec un dat. de pers. :</i> τινί, HDT. <i>1, 134, etc. ;</i> AR. <i>Nub. 689 ;</i> PLUT. <i>Lyc. 1,</i> qqn ; <i>avec un dat. de chose :</i> τινί, HDT. <i>2, 70,</i> qqe ch. ; <i>particul. en parl. d’obstacles :</i> ἐντ. τάφροις, XÉN. <i>An. 2, 3, 10 ; ou</i> λόφῳ, <i>An. 4, 2, 10,</i> rencontrer sur son chemin des fossés, une colline ; <i>rar. avec le gén</i>. ἐντ. λελυμένης τῆς γεφύρης, HDT. <i>4, 140,</i> trouver le pont rompu ; <i>abs</i>. ὁ ἐντυγχάνων, PLAT. <i>2 Alc. 144</i> b, <i>ou</i> ἐντυχών, THC. <i>4, 132 ;</i> IS. <i>44, 8 ; 76, 42 ;</i> ISOCR. <i>378</i> b, le premier venu ;<br><b>      2</b> <i>avec un suj. de chose,</i> tomber sur : τινί, sur qqn, <i>en parl. de la foudre,</i> XÉN. <i>Mem. 4, 3, 14 ; d’un malheur,</i> ESCHL. <i>Pers. 706 ;</i><br><b>   II</b> se rencontrer avec, <i>d’où :</i><br><b>      1</b> avoir une entrevue, un entretien avec, <i>dat</i>. PLAT. <i>Ap. 41</i> b ; PLUT. <i>Lyc. 1, Tim. 10 ; particul</i>. avoir des relations intimes avec, SOL. (PLUT. <i>Sol. 20</i>) ; PLUT. <i>Rom. 5 ;</i><br><b>      2</b> <i>particul</i>. intercéder auprès de, solliciter : τινί, SPT. <i>3Macc. 6, 37 ;</i> NT. <i>Ap. 25, 24,</i> qqn ; τινὶ περί τινος, POL. <i>4, 76, 9 ; ou</i> ὑπέρ τινος, PLUT. <i>Cato ma. 9,</i> qqn pour qqn : <i>avec l’inf</i>. PLUT. <i>Pomp. 55, ou avec</i> ὅπως, PLUT. <i>Ages. 25,</i> solliciter qqn de, <i>etc. ;</i><br><b>   III</b> <i>en parl. de livres, de lectures :</i> ἐντ. βιϐλίῳ, PLAT. <i>Conv. 177</i> b, avoir commerce avec un livre ; <i>d’où abs</i>. lire, POL. <i>1, 35, 6 ;</i> PLUT. <i>M. 675</i> b ; LUC. <i>Dem. enc. 27 ;</i> SPT. <i>2Macc. 2, 25 ; 15, 39, etc. ;</i> οἱ ἐντυγχάνοντες, POL. <i>1, 3, 10,</i> les lecteurs.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντυγχανω - ἐντυγχάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (4)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1794":"<h1>entulisso</h1>\n<p>Strong n° 1794 <i>Prononciation [en-too-lis'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>enrouler, envelopper ensemble</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·τυλίσσω</b>, <i>att</i>. <b>-ίττω</b> <span>(<i>ao</i>. ἐνετύλιξα)</span> <span>[ῠ]</span> envelopper dans, AR. <i>Pl. 692, Nub. 983 ;</i> ATH. <i>106</i> f ; NT. <i>Luc. 23, 53</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντυλισσω - ἐντυλίσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1795":"<h1>entupoo</h1>\n<p>Strong n° 1795 <i>Prononciation [en-too-po'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>graver, une empreinte (une figure)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·τυπόω-ῶ</b> <span>[ῠ]</span> empreindre dans : μορφήν, PLUT. <i>Per. 31,</i> graver une image (<i>p. opp. à</i> ἐκτυπόω, sculpter en relief) ; τι νομίσματι, ARSTT. <i>fr. 527 ; ou</i> ἐς νόμισμα, DC. <i>47, 25,</i> graver qqe ch. sur une monnaie ; <i>fig</i>. τὸ ἰδίωμα τῇ λέξει, LGN <i>10, 6,</i> marquer dans son style l’empreinte de son esprit ;<br><b><i>Moy.</i></b> graver (qqe ch. de soi) dans <i>ou</i> sur : τὸ ἑαυτοῦ πρόσωπον, ARSTT. <i>Mund. 6, 29,</i> ses propres traits.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">εντυποω - ἐντυπόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1796":"<h1>enubrizo</h1>\n<p>Strong n° 1796 <i>Prononciation [en-oo-brid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>insulter, outrager</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·υϐρίζω</b> <span>[ῠ]</span><br><b>      1</b> outrager, insulter dans : τινὰ ἐν κακοῖς, EUR. <i>El. 68,</i> qqn dans le malheur ;<br><b>      2</b> <i>p. ext</i>. outrager, insulter : τινά, SOPH. <i>Ph. 342 ;</i> τινί, POL. <i>10, 26, 3 ;</i> εἴς τινα, DS. <i>Exc. 527, 57,</i> outrager qqn ; <i>abs</i>. AR. <i>Th. 719</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενυβριζω - ἐνυβρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1797":"<h1>enupniazomai</h1>\n<p>Strong n° 1797 <i>Prononciation [en-oop-nee-ad'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>songer (divinement conduit), rêves</li>\n<li>métaph., être trompé par des images sensuelles et emmené vers une conduite impie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>ἐν·υπνιάζω</b>, rêver, ARSTT. <i>Insomn. 1, 9 ; Somn. 1, 1 ; H.A. 4, 10, 2, etc. ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. HPC. <i>V. med. 12</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. pass</i>. -ασθήσομαι <i>au sens moy</i>. SPT. <i>Joel 2, 28 ; ao. pass. inf</i>. -ασθῆναι <i>au sens moy</i>. SPT. <i>Gen. 37, 5, 6, 8</i>.<br><span><b>Étym</b>. ἐνύπνιον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενυπνιαζομαι - ἐνυπνιάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G1798":"<h1>enupnion</h1>\n<p>Strong n° 1798 <i>Prononciation [en-oop'-nee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un songe, un rêve</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐνύπνιον, ου (τὸ) :<br>      1</b> vision pendant le sommeil, songe, rêve, PD. <i>O. 13, 76 ;</i> HDT. <i>7, 16, 2 ;</i> XÉN. <i>Conv. 4, 48 ;</i> PLAT. <i>Crit. 44</i> a ; ὄψις ἐνυπνίου, HDT. <i>8, 54 ; ou</i> ὄψις ἐνυπνίων, ESCHL. <i>Pers. 518,</i> vision, visions en songe ; ἐνύπνιον ἰδεῖν, AR. <i>Vesp. 25 ;</i> PLAT. <i>Pol. 290</i> b, voir en songe ; κατ' ἐνύπνιον, ANTH. <i>11, 150,</i> en songe ;<br><b>      2</b> <i>adv</i>., en songe, IL. <i>2, 56 ;</i> OD. <i>14, 495 ;</i> AR. <i>Vesp. 1218 ; etc</i>.<br><span><b>Étym</b>. <i>neutre de</i> ἐνύπνιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενυπνιον - ἐνύπνιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1799":"<h1>enopion</h1>\n<p>Strong n° 1799 <i>Prononciation [en-o'-pee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>en présence de, devant\n<ol type=\"a\">\n<li>par rapport à la place occupée: ce qui est devant, contre, à l'opposé, vers où l'on peut tourner les yeux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ἐν·ώπιος, ος, ον :<br>   I</b> qui est face à face, THCR. <i>Idyl. 22, 152 ;</i> SPT. <i>Ex. 33, 11 ;</i><br><b>   II</b> <i>subst</i>. τὰ ἐνώπια :<br><b>      1</b> mur intérieur en face de la porte située au fond du vestibule, <i>p. opp. à</i> προνώπια, IL. <i>8, 435, etc. ;</i> OD. <i>4, 42, etc. ;</i><br><b>      2</b> aspect, ESCHL. <i>Suppl. 145 ;</i><br><b>   III</b> <i>adv</i>., ἐνώπιον, NT. <i>Rom. 12, 17 ;</i> GAL. <i>1, 20,</i> en face de, <i>gén</i>.<br><span><b>Étym</b>. ἐν, ὤψ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ενωπιον - ἐνώπιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n97 fois dans 88 versets de 15 livres bibliques (NT)\n<ul>\n<li>Luc (23)</li>\n<li>Jean (1)</li>\n<li>Actes (15)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (4)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (6)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (35)</li>\n</ul>\n</td></tr>\n</table>"};
